    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: A 3-year-old female infant is evaluated for a murmur. A harsh, holosystolic murmur is heard best at the left lower sternal border. The child is asymptomatic and growing well. What is the most likely diagnosis?', '["Atrial Septal Defect (ASD)", "Ventricular Septal Defect (VSD)", "Patent Ductus Arteriosus (PDA)", "Coarctation of the Aorta"]', 1, 'VSD is the most common congenital heart defect, presenting with a harsh, holosystolic murmur at the left lower sternal border. Small VSDs are asymptomatic. (Nelson Essentials)'),
    (v_topic_id, '2: A 1-week-old female infant with a known large VSD presents with tachypnea, diaphoresis during feeds, and poor weight gain. What is the most appropriate initial medical therapy?', '["Indomethacin", "Diuretics (e.g., Furosemide) and high-calorie formula", "Immediate surgical closure", "Prostaglandin E1"]', 1, 'Infants with large VSDs and heart failure are initially managed medically with diuretics and nutritional support to allow for growth before surgical repair. (Nelson Essentials)'),
    (v_topic_id, '3: In a patient with a Ventricular Septal Defect, the development of pulmonary hypertension and reversal of the shunt (right-to-left) leading to cyanosis is known as:', '["Cor pulmonale", "Tetralogy of Fallot", "Eisenmenger syndrome", "Ebstein anomaly"]', 2, 'Eisenmenger syndrome occurs when chronic left-to-right shunting causes pulmonary vascular disease, eventually reversing the shunt and causing cyanosis. (Blueprints)'),
    (v_topic_id, '4: Which of the following describes the typical natural history of a small, restrictive Ventricular Septal Defect?', '["Spontaneous closure in childhood", "High risk of sudden cardiac death", "Progression to heart failure", "Development of Eisenmenger syndrome"]', 0, 'The majority of small, muscular VSDs close spontaneously during childhood and do not require surgical intervention. (BRS Pediatrics)'),
    (v_topic_id, '5: A 2-week-old female infant has a holosystolic murmur at the left lower sternal border. An echocardiogram shows a large VSD. Which of the following chamber enlargements is most likely?', '["Right ventricle only", "Left atrium and Left ventricle", "Left atrium only", "Right atrium and Right ventricle"]', 1, 'A large VSD causes a left-to-right shunt. The extra blood goes to the lungs and returns to the left heart, causing LA and LV volume overload and dilation. (Nelson Essentials)'),
    (v_topic_id, '6: A 3-month-old female toddler is found to have a widely split and fixed S2 on routine examination. There is also a soft systolic ejection murmur at the left upper sternal border. What is the most likely diagnosis?', '["Atrial Septal Defect (ASD)", "Tetralogy of Fallot", "Ventricular Septal Defect (VSD)", "Pulmonary Stenosis"]', 0, 'A widely split and fixed S2 is the hallmark of an ASD. The systolic murmur is due to increased flow across the pulmonary valve. (Case Files Pediatrics)'),
    (v_topic_id, '7: An ostium primum Atrial Septal Defect is most commonly associated with which genetic syndrome?', '["Down syndrome (Trisomy 21)", "Turner syndrome", "DiGeorge syndrome", "Marfan syndrome"]', 0, 'Ostium primum ASDs and Atrioventricular Septal Defects (AVSDs) are highly associated with Down syndrome. (Blueprints)'),
    (v_topic_id, '8: What is the primary hemodynamic consequence of an unrepaired moderate-to-large Atrial Septal Defect over decades?', '["Left ventricular hypertrophy", "Premature coronary artery disease", "Right-sided heart volume overload and failure", "Aortic root dilation"]', 2, 'Chronic left-to-right shunting through an ASD leads to right atrial and right ventricular volume overload, eventually causing right heart failure or arrhythmias in adulthood. (BRS Pediatrics)'),
    (v_topic_id, '9: A 3-month-old boy with an unrepaired ASD presents with a sudden onset stroke. What is the most likely mechanism?', '["Hemorrhage from a berry aneurysm", "Atherosclerotic plaque rupture", "Infective endocarditis", "Paradoxical embolus"]', 3, 'A venous thrombus can cross through the ASD (right-to-left shunting during transient pressure changes) into the systemic circulation, causing a paradoxical embolus and stroke. (Nelson Essentials)'),
    (v_topic_id, '10: Which type of Atrial Septal Defect is the most common?', '["Ostium primum", "Coronary sinus", "Sinus venosus", "Ostium secundum"]', 3, 'The ostium secundum defect, located in the central portion of the atrial septum, is the most common type of ASD. (Blueprints)'),
    (v_topic_id, '11: A 1-month-old premature infant has a continuous, machine-like murmur heard best at the left infraclavicular area. Bounding peripheral pulses are noted. What is the most likely diagnosis?', '["Patent Ductus Arteriosus (PDA)", "Truncus Arteriosus", "Aortic Regurgitation", "Coarctation of the Aorta"]', 0, 'A continuous machine-like murmur and bounding pulses (due to widened pulse pressure) are classic findings of a Patent Ductus Arteriosus. (Nelson Essentials)'),
    (v_topic_id, '12: What medication is used to induce closure of a Patent Ductus Arteriosus in a premature infant?', '["Spironolactone", "Indomethacin (or Ibuprofen)", "Prostaglandin E1", "Acetaminophen"]', 1, 'NSAIDs like indomethacin or ibuprofen inhibit prostaglandin synthesis, which promotes the closure of the ductus arteriosus. (BRS Pediatrics)'),
    (v_topic_id, '13: In which of the following congenital heart defects is a Patent Ductus Arteriosus essential for survival (ductal-dependent)?', '["Transposition of the Great Arteries", "Atrial Septal Defect", "Small Ventricular Septal Defect", "Mild Pulmonary Stenosis"]', 0, 'In Transposition of the Great Arteries, mixing of oxygenated and deoxygenated blood is required for survival, making it a ductal-dependent lesion. (Case Files Pediatrics)'),
    (v_topic_id, '14: Maternal infection with which organism during the first trimester is classically associated with Patent Ductus Arteriosus?', '["Herpes Simplex Virus", "Cytomegalovirus", "Rubella", "Toxoplasma gondii"]', 2, 'Congenital rubella syndrome is classically associated with cataracts, sensorineural hearing loss, and congenital heart defects, most notably PDA and pulmonary artery stenosis. (Nelson Essentials)'),
    (v_topic_id, '15: Which medication is administered to maintain the patency of the ductus arteriosus in a newborn with ductal-dependent congenital heart disease?', '["Milrinone", "Prostaglandin E1 (Alprostadil)", "Epinephrine", "Indomethacin"]', 1, 'Prostaglandin E1 is used to keep the ductus arteriosus open until surgical intervention can be performed in ductal-dependent lesions. (Blueprints)'),
    (v_topic_id, '16: A 2-month-old boy is found to have hypertension in the upper extremities and diminished, delayed femoral pulses. What is the most likely diagnosis?', '["Aortic Stenosis", "Patent Ductus Arteriosus", "Coarctation of the Aorta", "Renal Artery Stenosis"]', 2, 'Coarctation of the aorta presents with a blood pressure discrepancy between the upper and lower extremities and decreased or delayed femoral pulses. (Nelson Essentials)'),
    (v_topic_id, '17: Which genetic syndrome has a high association with Coarctation of the Aorta?', '["Marfan syndrome", "DiGeorge syndrome", "Down syndrome", "Turner syndrome"]', 3, 'Turner syndrome (45,X) is strongly associated with left-sided heart lesions, particularly coarctation of the aorta and bicuspid aortic valve. (BRS Pediatrics)'),
    (v_topic_id, '18: A chest X-ray of an older child with undiagnosed Coarctation of the Aorta is most likely to show:', '["Egg on a string appearance", "Rib notching and a ''''figure 3'''' sign", "Boot-shaped heart", "Snowman sign"]', 1, 'Rib notching is caused by enlarged collateral intercostal arteries. The ''figure 3'' sign is formed by the pre-stenotic dilation, the coarctation itself, and the post-stenotic dilation. (Case Files Pediatrics)'),
    (v_topic_id, '19: Coarctation of the Aorta is most commonly associated with which other congenital cardiac anomaly?', '["Mitral valve prolapse", "Bicuspid aortic valve", "Pulmonary atresia", "Ebstein anomaly"]', 1, 'Up to 85% of patients with coarctation of the aorta also have a bicuspid aortic valve. (Blueprints)'),
    (v_topic_id, '20: A neonate with critical Coarctation of the Aorta presents with sudden shock and severe acidosis on day 3 of life. What is the immediate life-saving intervention?', '["Intravenous Prostaglandin E1", "Intravenous fluid bolus alone", "Intravenous Indomethacin", "Immediate heart transplant"]', 0, 'In critical coarctation, lower body perfusion is ductal-dependent. Closure of the PDA leads to shock. PGE1 reopens the ductus. (Nelson Essentials)'),
    (v_topic_id, '21: A 2-year-old female toddler presents with cyanosis during episodes of crying or feeding. The cyanosis improves when the child is placed in a knee-chest position. What is the most likely diagnosis?', '["Transposition of the Great Arteries", "Truncus Arteriosus", "Tetralogy of Fallot", "Tricuspid Atresia"]', 2, 'These ''tet spells'' are characteristic of Tetralogy of Fallot. The knee-chest position increases systemic vascular resistance, decreasing the right-to-left shunt and improving pulmonary blood flow. (Nelson Essentials)'),
    (v_topic_id, '22: Which of the following is NOT one of the four classic components of Tetralogy of Fallot?', '["Pulmonary Stenosis", "Right Ventricular Hypertrophy", "Ventricular Septal Defect", "Atrial Septal Defect"]', 3, 'The components (PROVe) are Pulmonary stenosis (RV outflow tract obstruction), Right ventricular hypertrophy, Overriding aorta, and VSD. (BRS Pediatrics)'),
    (v_topic_id, '23: What is the classic chest X-ray finding in a patient with Tetralogy of Fallot?', '["Boot-shaped heart (Coeur en sabot)", "Egg on a string", "Figure 3 sign", "Snowman sign"]', 0, 'The boot-shaped heart is due to right ventricular hypertrophy (upturned apex) and a concave main pulmonary artery segment. (Case Files Pediatrics)'),
    (v_topic_id, '24: In Tetralogy of Fallot, the degree of cyanosis and clinical severity is most primarily determined by the severity of:', '["The size of the VSD", "The amount of right ventricular hypertrophy", "Right ventricular outflow tract obstruction (Pulmonary stenosis)", "The degree of aortic override"]', 2, 'The severity of pulmonary stenosis dictates the amount of right-to-left shunting across the VSD, which determines the degree of cyanosis. (Blueprints)'),
    (v_topic_id, '25: A 2-month-old with Tetralogy of Fallot presents with an acute hypercyanotic spell (Tet spell). After placing the child in a knee-chest position, which medication is most appropriate to administer?', '["Diuretics", "Morphine and Oxygen", "Epinephrine", "Digoxin"]', 1, 'Management of a Tet spell includes knee-chest position, oxygen, morphine (decreases sympathetic drive and infundibular spasm), and IV fluids. Beta-blockers or phenylephrine can also be used. (Nelson Essentials)'),
    (v_topic_id, '26: A neonate presents with profound cyanosis immediately after birth. Echocardiogram reveals that the aorta arises from the right ventricle and the pulmonary artery from the left ventricle. What is the diagnosis?', '["Transposition of the Great Arteries (TGA)", "Total Anomalous Pulmonary Venous Return", "Tetralogy of Fallot", "Truncus Arteriosus"]', 0, 'TGA is the most common cyanotic heart defect presenting in the immediate newborn period. It creates two parallel circulatory systems. (Nelson Essentials)'),
    (v_topic_id, '27: In a newborn with Transposition of the Great Arteries, survival before surgical repair depends entirely on:', '["Keeping the infant in a knee-chest position", "Administering Indomethacin", "Mixing of blood via a PDA, ASD, or VSD", "Administration of 100% oxygen"]', 2, 'Because the pulmonary and systemic circulations are in parallel, life is impossible without mixing of oxygenated and deoxygenated blood through a shunt (PDA, PFO/ASD, or VSD). (Blueprints)'),
    (v_topic_id, '28: What is the classic chest X-ray appearance in a neonate with Transposition of the Great Arteries?', '["Wall-to-wall heart", "Snowman sign", "''Egg on a string'' with a narrow mediastinum", "Boot-shaped heart"]', 2, 'The ''egg on a string'' appearance is due to the anteroposterior relationship of the great vessels (causing a narrow superior mediastinum) and a globular heart. (BRS Pediatrics)'),
    (v_topic_id, '29: If Prostaglandin E1 fails to improve oxygenation in a severely cyanotic neonate with Transposition of the Great Arteries, what is the next best step?', '["High-frequency oscillatory ventilation", "Balloon atrial septostomy (Rashkind procedure)", "Immediate open-heart surgery", "Administration of Indomethacin"]', 1, 'If the PFO is restrictive and PGE1 isn''t enough, a balloon atrial septostomy is performed via catheterization to tear the atrial septum and improve mixing. (Case Files Pediatrics)'),
    (v_topic_id, '30: Transposition of the Great Arteries is strongly associated with which maternal condition?', '["Maternal lithium use", "Maternal diabetes mellitus", "Maternal lupus", "Maternal rubella infection"]', 1, 'Infants of diabetic mothers have a significantly increased risk of congenital heart defects, including TGA, VSD, and hypertrophic cardiomyopathy. (Nelson Essentials)'),
    (v_topic_id, '31: A neonate is found to have a single large vessel arising from the base of the heart that gives rise to the coronary, pulmonary, and systemic arteries. A VSD is also present. Diagnosis?', '["Truncus Arteriosus", "Tricuspid Atresia", "Tetralogy of Fallot", "Transposition of the Great Arteries"]', 0, 'Truncus arteriosus involves failure of the conotruncal septum to form, resulting in a single great vessel and a mandatory VSD. (Blueprints)'),
    (v_topic_id, '32: Truncus Arteriosus and Tetralogy of Fallot are frequently associated with microdeletion of chromosome 22q11. What syndrome is this?', '["DiGeorge syndrome", "Williams syndrome", "Turner syndrome", "Down syndrome"]', 0, 'DiGeorge syndrome (22q11.2 deletion) is associated with conotruncal cardiac defects (Truncus, ToF), abnormal facies, thymic hypoplasia, cleft palate, and hypocalcemia. (Nelson Essentials)'),
    (v_topic_id, '33: A cyanotic newborn has an ECG showing Left Axis Deviation and Left Ventricular Hypertrophy (LVH). Right ventricular forces are completely absent. What is the most likely diagnosis?', '["Tetralogy of Fallot", "Transposition of the Great Arteries", "Pulmonary Stenosis", "Tricuspid Atresia"]', 3, 'Most cyanotic congenital heart defects present with Right Axis Deviation and RVH. Tricuspid Atresia is unique as it causes hypoplasia of the RV, leading to LAD and LVH. (Case Files Pediatrics)'),
    (v_topic_id, '34: For an infant with Tricuspid Atresia to survive, blood must bypass the right atrium. What obligatory defect must be present?', '["Pulmonary Atresia", "Atrial Septal Defect (ASD) or Patent Foramen Ovale (PFO)", "Coarctation of the Aorta", "Aortic Stenosis"]', 1, 'Since the tricuspid valve is absent, all systemic venous blood must cross the atrial septum (via ASD/PFO) to the left atrium to reach the left ventricle. (Blueprints)'),
    (v_topic_id, '35: A neonate with cyanosis has a chest X-ray demonstrating a ''snowman'' (or figure-8) appearance of the cardiac silhouette. What is the diagnosis?', '["Tetralogy of Fallot", "Coarctation of the Aorta", "Total Anomalous Pulmonary Venous Return (TAPVR)", "Transposition of the Great Arteries"]', 2, 'In TAPVR, all pulmonary veins drain into the systemic venous circulation (e.g., SVC). The dilated vertical vein and SVC above the heart create the ''head'' of the snowman. (Nelson Essentials)'),
    (v_topic_id, '36: A neonate presents with cyanosis. Echocardiogram shows downward displacement of the tricuspid valve leaflets into the right ventricle, causing ''atrialization'' of the right ventricle. Diagnosis?', '["Ebstein Anomaly", "Tricuspid Atresia", "Truncus Arteriosus", "Tetralogy of Fallot"]', 0, 'Ebstein anomaly is characterized by apical displacement of the tricuspid valve, leading to a small functional RV and severe tricuspid regurgitation. (Blueprints)'),
    (v_topic_id, '37: Maternal use of which psychiatric medication during pregnancy is classically associated with Ebstein Anomaly?', '["Valproic acid", "Lithium", "Carbamazepine", "SSRI (e.g., Fluoxetine)"]', 1, 'Lithium exposure in the first trimester is classically linked to a higher risk of Ebstein anomaly. (BRS Pediatrics)'),
    (v_topic_id, '38: Patients with Ebstein Anomaly have a high incidence of which cardiac arrhythmia?', '["Ventricular Fibrillation", "Torsades de pointes", "First-degree AV block", "Wolff-Parkinson-White (WPW) syndrome"]', 3, 'Ebstein anomaly is strongly associated with accessory conduction pathways, leading to WPW syndrome and supraventricular tachycardias. (Nelson Essentials)'),
    (v_topic_id, '39: A 6-month-old newborn presents with shock, weak pulses, and gray cyanosis shortly after the ductus arteriosus begins to close. Echocardiogram shows a severely underdeveloped left ventricle. Diagnosis?', '["Ebstein Anomaly", "Hypoplastic Left Heart Syndrome (HLHS)", "Tricuspid Atresia", "Tetralogy of Fallot"]', 1, 'HLHS involves hypoplasia of the left ventricle, mitral valve, and aorta. Systemic blood flow is entirely dependent on a Patent Ductus Arteriosus (PDA). (Case Files Pediatrics)'),
    (v_topic_id, '40: What is the primary staged surgical palliation pathway for Hypoplastic Left Heart Syndrome (HLHS)?', '["Blalock-Taussig shunt alone", "Ross procedure", "Arterial switch operation", "Norwood procedure, followed by Glenn, then Fontan"]', 3, 'The Norwood procedure (stage 1) constructs a new aorta, followed by the bidirectional Glenn (stage 2), and the Fontan completion (stage 3) to route venous return directly to the lungs. (Nelson Essentials)'),
    (v_topic_id, '41: Which of the following is an acyanotic congenital heart defect?', '["Truncus Arteriosus", "Tetralogy of Fallot", "Transposition of the Great Arteries", "Ventricular Septal Defect"]', 3, 'VSD, ASD, and PDA are left-to-right shunts, which are acyanotic. The ''5 Ts'' (ToF, TGA, Truncus, Tricuspid Atresia, TAPVR) are right-to-left shunts and are cyanotic. (Blueprints)'),
    (v_topic_id, '42: The ''5 Ts'' of cyanotic congenital heart disease include all EXCEPT:', '["Tetralogy of Fallot", "Truncus Arteriosus", "Transposition of the Great Arteries", "Tachycardia induced cardiomyopathy"]', 3, 'The 5 Ts are Tetralogy, Transposition, Truncus, Tricuspid Atresia, and TAPVR. (BRS Pediatrics)'),
    (v_topic_id, '43: Which of the following patients requires antibiotic prophylaxis prior to a dental procedure?', '["A child with an isolated, repaired ASD (surgery 2 years ago)", "A child with a physiologic flow murmur", "A child with a history of Kawasaki disease without aneurysms", "A child with an unrepaired cyanotic congenital heart defect"]', 3, 'Endocarditis prophylaxis is recommended for unrepaired cyanotic CHD, completely repaired CHD within the first 6 months, repaired CHD with residual defects, or prior history of endocarditis. (AHA Guidelines/Nelson)'),
    (v_topic_id, '44: A 2-week-old presents with 5 days of fever, bilateral non-exudative conjunctivitis, strawberry tongue, cervical lymphadenopathy, and a polymorphous rash. What is the most critical cardiac complication to prevent?', '["Rheumatic mitral stenosis", "Ventricular septal rupture", "Aortic dissection", "Coronary artery aneurysms"]', 3, 'This is classic Kawasaki disease. The primary goal of treatment with IVIG and aspirin is to prevent the development of coronary artery aneurysms. (Nelson Essentials)'),
    (v_topic_id, '45: A 1-month-old immigrant presents with a history of recurrent sore throats and now has a new, rumbling diastolic murmur at the apex with an opening snap. What is the most likely diagnosis?', '["Congenital aortic stenosis", "Infective endocarditis", "Ventricular Septal Defect", "Rheumatic mitral stenosis"]', 3, 'A rumbling diastolic murmur with an opening snap is classic for mitral stenosis, which is almost always a late consequence of Rheumatic Heart Disease following Group A Strep pharyngitis. (Blueprints)'),
    (v_topic_id, '46: A 2-year-old male toddler is evaluated for a murmur. A harsh, holosystolic murmur is heard best at the parasternal border. The child is asymptomatic and growing well. What is the most likely diagnosis?', '["Ventricular Septal Defect (VSD)", "Coarctation of the Aorta", "Patent Ductus Arteriosus (PDA)", "Atrial Septal Defect (ASD)"]', 0, 'VSD is the most common congenital heart defect, presenting with a harsh, holosystolic murmur at the left lower sternal border. Small VSDs are asymptomatic. (Nelson Essentials)'),
    (v_topic_id, '47: A 2-month-old girl with a known large VSD presents with tachypnea, diaphoresis during feeds, and poor weight gain. What is the most appropriate initial medical therapy?', '["Diuretics (e.g., Furosemide) and high-calorie formula", "Immediate surgical closure", "Prostaglandin E1", "Indomethacin"]', 0, 'Infants with large VSDs and heart failure are initially managed medically with diuretics and nutritional support to allow for growth before surgical repair. (Nelson Essentials)'),
    (v_topic_id, '48: In a patient with a Ventricular Septal Defect, the development of pulmonary hypertension and reversal of the shunt (right-to-left) leading to cyanosis is known as:', '["Tetralogy of Fallot", "Eisenmenger syndrome", "Cor pulmonale", "Ebstein anomaly"]', 1, 'Eisenmenger syndrome occurs when chronic left-to-right shunting causes pulmonary vascular disease, eventually reversing the shunt and causing cyanosis. (Blueprints)'),
    (v_topic_id, '49: Which of the following describes the typical natural history of a small, restrictive Ventricular Septal Defect?', '["Development of Eisenmenger syndrome", "Progression to heart failure", "High risk of sudden cardiac death", "Spontaneous closure in childhood"]', 3, 'The majority of small, muscular VSDs close spontaneously during childhood and do not require surgical intervention. (BRS Pediatrics)'),
    (v_topic_id, '50: A 1-year-old male infant has a holosystolic murmur at the left lower sternal border. An echocardiogram shows a large VSD. Which of the following chamber enlargements is most likely?', '["Right ventricle only", "Right atrium and Right ventricle", "Left atrium and Left ventricle", "Left atrium only"]', 2, 'A large VSD causes a left-to-right shunt. The extra blood goes to the lungs and returns to the left heart, causing LA and LV volume overload and dilation. (Nelson Essentials)'),
    (v_topic_id, '51: A 4-year-old female toddler is found to have a widely split and fixed S2 on routine examination. There is also a soft systolic ejection murmur at the left upper sternal border. What is the most likely diagnosis?', '["Atrial Septal Defect (ASD)", "Ventricular Septal Defect (VSD)", "Pulmonary Stenosis", "Tetralogy of Fallot"]', 0, 'A widely split and fixed S2 is the hallmark of an ASD. The systolic murmur is due to increased flow across the pulmonary valve. (Case Files Pediatrics)'),
    (v_topic_id, '52: An ostium primum Atrial Septal Defect is most commonly associated with which genetic syndrome?', '["Turner syndrome", "DiGeorge syndrome", "Down syndrome (Trisomy 21)", "Marfan syndrome"]', 2, 'Ostium primum ASDs and Atrioventricular Septal Defects (AVSDs) are highly associated with Down syndrome. (Blueprints)'),
    (v_topic_id, '53: What is the primary hemodynamic consequence of an unrepaired moderate-to-large Atrial Septal Defect over decades?', '["Left ventricular hypertrophy", "Right-sided heart volume overload and failure", "Premature coronary artery disease", "Aortic root dilation"]', 1, 'Chronic left-to-right shunting through an ASD leads to right atrial and right ventricular volume overload, eventually causing right heart failure or arrhythmias in adulthood. (BRS Pediatrics)'),
    (v_topic_id, '54: A 2-month-old girl with an unrepaired ASD presents with a sudden onset stroke. What is the most likely mechanism?', '["Infective endocarditis", "Paradoxical embolus", "Hemorrhage from a berry aneurysm", "Atherosclerotic plaque rupture"]', 1, 'A venous thrombus can cross through the ASD (right-to-left shunting during transient pressure changes) into the systemic circulation, causing a paradoxical embolus and stroke. (Nelson Essentials)'),
    (v_topic_id, '55: Which type of Atrial Septal Defect is the most common?', '["Coronary sinus", "Ostium primum", "Ostium secundum", "Sinus venosus"]', 2, 'The ostium secundum defect, located in the central portion of the atrial septum, is the most common type of ASD. (Blueprints)'),
    (v_topic_id, '56: A 2-day-old premature infant has a continuous, machine-like murmur heard best at the left infraclavicular area. Bounding peripheral pulses are noted. What is the most likely diagnosis?', '["Patent Ductus Arteriosus (PDA)", "Aortic Regurgitation", "Coarctation of the Aorta", "Truncus Arteriosus"]', 0, 'A continuous machine-like murmur and bounding pulses (due to widened pulse pressure) are classic findings of a Patent Ductus Arteriosus. (Nelson Essentials)'),
    (v_topic_id, '57: What medication is used to induce closure of a Patent Ductus Arteriosus in a premature infant?', '["Acetaminophen", "Spironolactone", "Indomethacin (or Ibuprofen)", "Prostaglandin E1"]', 2, 'NSAIDs like indomethacin or ibuprofen inhibit prostaglandin synthesis, which promotes the closure of the ductus arteriosus. (BRS Pediatrics)'),
    (v_topic_id, '58: In which of the following congenital heart defects is a Patent Ductus Arteriosus essential for survival (ductal-dependent)?', '["Atrial Septal Defect", "Mild Pulmonary Stenosis", "Transposition of the Great Arteries", "Small Ventricular Septal Defect"]', 2, 'In Transposition of the Great Arteries, mixing of oxygenated and deoxygenated blood is required for survival, making it a ductal-dependent lesion. (Case Files Pediatrics)'),
    (v_topic_id, '59: Maternal infection with which organism during the first trimester is classically associated with Patent Ductus Arteriosus?', '["Cytomegalovirus", "Rubella", "Toxoplasma gondii", "Herpes Simplex Virus"]', 1, 'Congenital rubella syndrome is classically associated with cataracts, sensorineural hearing loss, and congenital heart defects, most notably PDA and pulmonary artery stenosis. (Nelson Essentials)'),
    (v_topic_id, '60: Which medication is administered to maintain the patency of the ductus arteriosus in a newborn with ductal-dependent congenital heart disease?', '["Milrinone", "Indomethacin", "Epinephrine", "Prostaglandin E1 (Alprostadil)"]', 3, 'Prostaglandin E1 is used to keep the ductus arteriosus open until surgical intervention can be performed in ductal-dependent lesions. (Blueprints)'),
    (v_topic_id, '61: A 1-month-old male toddler is found to have hypertension in the upper extremities and diminished, delayed femoral pulses. What is the most likely diagnosis?', '["Coarctation of the Aorta", "Patent Ductus Arteriosus", "Renal Artery Stenosis", "Aortic Stenosis"]', 0, 'Coarctation of the aorta presents with a blood pressure discrepancy between the upper and lower extremities and decreased or delayed femoral pulses. (Nelson Essentials)'),
    (v_topic_id, '62: Which genetic syndrome has a high association with Coarctation of the Aorta?', '["Marfan syndrome", "DiGeorge syndrome", "Down syndrome", "Turner syndrome"]', 3, 'Turner syndrome (45,X) is strongly associated with left-sided heart lesions, particularly coarctation of the aorta and bicuspid aortic valve. (BRS Pediatrics)'),
    (v_topic_id, '63: A chest X-ray of an older child with undiagnosed Coarctation of the Aorta is most likely to show:', '["Rib notching and a ''''figure 3'''' sign", "Boot-shaped heart", "Snowman sign", "Egg on a string appearance"]', 0, 'Rib notching is caused by enlarged collateral intercostal arteries. The ''figure 3'' sign is formed by the pre-stenotic dilation, the coarctation itself, and the post-stenotic dilation. (Case Files Pediatrics)'),
    (v_topic_id, '64: Coarctation of the Aorta is most commonly associated with which other congenital cardiac anomaly?', '["Bicuspid aortic valve", "Pulmonary atresia", "Mitral valve prolapse", "Ebstein anomaly"]', 0, 'Up to 85% of patients with coarctation of the aorta also have a bicuspid aortic valve. (Blueprints)'),
    (v_topic_id, '65: A neonate with critical Coarctation of the Aorta presents with sudden shock and severe acidosis on day 3 of life. What is the immediate life-saving intervention?', '["Intravenous Indomethacin", "Immediate heart transplant", "Intravenous fluid bolus alone", "Intravenous Prostaglandin E1"]', 3, 'In critical coarctation, lower body perfusion is ductal-dependent. Closure of the PDA leads to shock. PGE1 reopens the ductus. (Nelson Essentials)'),
    (v_topic_id, '66: A 1-year-old female infant presents with cyanosis during episodes of crying or feeding. The cyanosis improves when the child is placed in a knee-chest position. What is the most likely diagnosis?', '["Transposition of the Great Arteries", "Tricuspid Atresia", "Tetralogy of Fallot", "Truncus Arteriosus"]', 2, 'These ''tet spells'' are characteristic of Tetralogy of Fallot. The knee-chest position increases systemic vascular resistance, decreasing the right-to-left shunt and improving pulmonary blood flow. (Nelson Essentials)'),
    (v_topic_id, '67: Which of the following is NOT one of the four classic components of Tetralogy of Fallot?', '["Pulmonary Stenosis", "Atrial Septal Defect", "Right Ventricular Hypertrophy", "Ventricular Septal Defect"]', 1, 'The components (PROVe) are Pulmonary stenosis (RV outflow tract obstruction), Right ventricular hypertrophy, Overriding aorta, and VSD. (BRS Pediatrics)'),
    (v_topic_id, '68: What is the classic chest X-ray finding in a patient with Tetralogy of Fallot?', '["Snowman sign", "Egg on a string", "Boot-shaped heart (Coeur en sabot)", "Figure 3 sign"]', 2, 'The boot-shaped heart is due to right ventricular hypertrophy (upturned apex) and a concave main pulmonary artery segment. (Case Files Pediatrics)'),
    (v_topic_id, '69: In Tetralogy of Fallot, the degree of cyanosis and clinical severity is most primarily determined by the severity of:', '["The degree of aortic override", "The size of the VSD", "Right ventricular outflow tract obstruction (Pulmonary stenosis)", "The amount of right ventricular hypertrophy"]', 2, 'The severity of pulmonary stenosis dictates the amount of right-to-left shunting across the VSD, which determines the degree of cyanosis. (Blueprints)'),
    (v_topic_id, '70: A 3-year-old with Tetralogy of Fallot presents with an acute hypercyanotic spell (Tet spell). After placing the child in a knee-chest position, which medication is most appropriate to administer?', '["Morphine and Oxygen", "Digoxin", "Diuretics", "Epinephrine"]', 0, 'Management of a Tet spell includes knee-chest position, oxygen, morphine (decreases sympathetic drive and infundibular spasm), and IV fluids. Beta-blockers or phenylephrine can also be used. (Nelson Essentials)'),
    (v_topic_id, '71: A neonate presents with profound cyanosis immediately after birth. Echocardiogram reveals that the aorta arises from the right ventricle and the pulmonary artery from the left ventricle. What is the diagnosis?', '["Total Anomalous Pulmonary Venous Return", "Transposition of the Great Arteries (TGA)", "Truncus Arteriosus", "Tetralogy of Fallot"]', 1, 'TGA is the most common cyanotic heart defect presenting in the immediate newborn period. It creates two parallel circulatory systems. (Nelson Essentials)'),
    (v_topic_id, '72: In a newborn with Transposition of the Great Arteries, survival before surgical repair depends entirely on:', '["Mixing of blood via a PDA, ASD, or VSD", "Administration of 100% oxygen", "Keeping the infant in a knee-chest position", "Administering Indomethacin"]', 0, 'Because the pulmonary and systemic circulations are in parallel, life is impossible without mixing of oxygenated and deoxygenated blood through a shunt (PDA, PFO/ASD, or VSD). (Blueprints)'),
    (v_topic_id, '73: What is the classic chest X-ray appearance in a neonate with Transposition of the Great Arteries?', '["Boot-shaped heart", "Snowman sign", "Wall-to-wall heart", "''Egg on a string'' with a narrow mediastinum"]', 3, 'The ''egg on a string'' appearance is due to the anteroposterior relationship of the great vessels (causing a narrow superior mediastinum) and a globular heart. (BRS Pediatrics)'),
    (v_topic_id, '74: If Prostaglandin E1 fails to improve oxygenation in a severely cyanotic neonate with Transposition of the Great Arteries, what is the next best step?', '["High-frequency oscillatory ventilation", "Immediate open-heart surgery", "Balloon atrial septostomy (Rashkind procedure)", "Administration of Indomethacin"]', 2, 'If the PFO is restrictive and PGE1 isn''t enough, a balloon atrial septostomy is performed via catheterization to tear the atrial septum and improve mixing. (Case Files Pediatrics)'),
    (v_topic_id, '75: Transposition of the Great Arteries is strongly associated with which maternal condition?', '["Maternal rubella infection", "Maternal diabetes mellitus", "Maternal lupus", "Maternal lithium use"]', 1, 'Infants of diabetic mothers have a significantly increased risk of congenital heart defects, including TGA, VSD, and hypertrophic cardiomyopathy. (Nelson Essentials)'),
    (v_topic_id, '76: A neonate is found to have a single large vessel arising from the base of the heart that gives rise to the coronary, pulmonary, and systemic arteries. A VSD is also present. Diagnosis?', '["Tricuspid Atresia", "Transposition of the Great Arteries", "Truncus Arteriosus", "Tetralogy of Fallot"]', 2, 'Truncus arteriosus involves failure of the conotruncal septum to form, resulting in a single great vessel and a mandatory VSD. (Blueprints)'),
    (v_topic_id, '77: Truncus Arteriosus and Tetralogy of Fallot are frequently associated with microdeletion of chromosome 22q11. What syndrome is this?', '["Down syndrome", "DiGeorge syndrome", "Williams syndrome", "Turner syndrome"]', 1, 'DiGeorge syndrome (22q11.2 deletion) is associated with conotruncal cardiac defects (Truncus, ToF), abnormal facies, thymic hypoplasia, cleft palate, and hypocalcemia. (Nelson Essentials)'),
    (v_topic_id, '78: A cyanotic newborn has an ECG showing Left Axis Deviation and Left Ventricular Hypertrophy (LVH). Right ventricular forces are completely absent. What is the most likely diagnosis?', '["Transposition of the Great Arteries", "Pulmonary Stenosis", "Tetralogy of Fallot", "Tricuspid Atresia"]', 3, 'Most cyanotic congenital heart defects present with Right Axis Deviation and RVH. Tricuspid Atresia is unique as it causes hypoplasia of the RV, leading to LAD and LVH. (Case Files Pediatrics)'),
    (v_topic_id, '79: For an infant with Tricuspid Atresia to survive, blood must bypass the right atrium. What obligatory defect must be present?', '["Coarctation of the Aorta", "Aortic Stenosis", "Atrial Septal Defect (ASD) or Patent Foramen Ovale (PFO)", "Pulmonary Atresia"]', 2, 'Since the tricuspid valve is absent, all systemic venous blood must cross the atrial septum (via ASD/PFO) to the left atrium to reach the left ventricle. (Blueprints)'),
    (v_topic_id, '80: A neonate with cyanosis has a chest X-ray demonstrating a ''snowman'' (or figure-8) appearance of the cardiac silhouette. What is the diagnosis?', '["Transposition of the Great Arteries", "Tetralogy of Fallot", "Total Anomalous Pulmonary Venous Return (TAPVR)", "Coarctation of the Aorta"]', 2, 'In TAPVR, all pulmonary veins drain into the systemic venous circulation (e.g., SVC). The dilated vertical vein and SVC above the heart create the ''head'' of the snowman. (Nelson Essentials)'),
    (v_topic_id, '81: A neonate presents with cyanosis. Echocardiogram shows downward displacement of the tricuspid valve leaflets into the right ventricle, causing ''atrialization'' of the right ventricle. Diagnosis?', '["Tetralogy of Fallot", "Truncus Arteriosus", "Ebstein Anomaly", "Tricuspid Atresia"]', 2, 'Ebstein anomaly is characterized by apical displacement of the tricuspid valve, leading to a small functional RV and severe tricuspid regurgitation. (Blueprints)'),
    (v_topic_id, '82: Maternal use of which psychiatric medication during pregnancy is classically associated with Ebstein Anomaly?', '["Lithium", "Valproic acid", "SSRI (e.g., Fluoxetine)", "Carbamazepine"]', 0, 'Lithium exposure in the first trimester is classically linked to a higher risk of Ebstein anomaly. (BRS Pediatrics)'),
    (v_topic_id, '83: Patients with Ebstein Anomaly have a high incidence of which cardiac arrhythmia?', '["Ventricular Fibrillation", "First-degree AV block", "Torsades de pointes", "Wolff-Parkinson-White (WPW) syndrome"]', 3, 'Ebstein anomaly is strongly associated with accessory conduction pathways, leading to WPW syndrome and supraventricular tachycardias. (Nelson Essentials)'),
    (v_topic_id, '84: A 2-year-old newborn presents with shock, weak pulses, and gray cyanosis shortly after the ductus arteriosus begins to close. Echocardiogram shows a severely underdeveloped left ventricle. Diagnosis?', '["Tricuspid Atresia", "Tetralogy of Fallot", "Ebstein Anomaly", "Hypoplastic Left Heart Syndrome (HLHS)"]', 3, 'HLHS involves hypoplasia of the left ventricle, mitral valve, and aorta. Systemic blood flow is entirely dependent on a Patent Ductus Arteriosus (PDA). (Case Files Pediatrics)'),
    (v_topic_id, '85: What is the primary staged surgical palliation pathway for Hypoplastic Left Heart Syndrome (HLHS)?', '["Blalock-Taussig shunt alone", "Ross procedure", "Arterial switch operation", "Norwood procedure, followed by Glenn, then Fontan"]', 3, 'The Norwood procedure (stage 1) constructs a new aorta, followed by the bidirectional Glenn (stage 2), and the Fontan completion (stage 3) to route venous return directly to the lungs. (Nelson Essentials)'),
    (v_topic_id, '86: Which of the following is an acyanotic congenital heart defect?', '["Transposition of the Great Arteries", "Truncus Arteriosus", "Tetralogy of Fallot", "Ventricular Septal Defect"]', 3, 'VSD, ASD, and PDA are left-to-right shunts, which are acyanotic. The ''5 Ts'' (ToF, TGA, Truncus, Tricuspid Atresia, TAPVR) are right-to-left shunts and are cyanotic. (Blueprints)'),
    (v_topic_id, '87: The ''5 Ts'' of cyanotic congenital heart disease include all EXCEPT:', '["Tetralogy of Fallot", "Tachycardia induced cardiomyopathy", "Truncus Arteriosus", "Transposition of the Great Arteries"]', 1, 'The 5 Ts are Tetralogy, Transposition, Truncus, Tricuspid Atresia, and TAPVR. (BRS Pediatrics)'),
    (v_topic_id, '88: Which of the following patients requires antibiotic prophylaxis prior to a dental procedure?', '["A child with a physiologic flow murmur", "A child with an unrepaired cyanotic congenital heart defect", "A child with an isolated, repaired ASD (surgery 2 years ago)", "A child with a history of Kawasaki disease without aneurysms"]', 1, 'Endocarditis prophylaxis is recommended for unrepaired cyanotic CHD, completely repaired CHD within the first 6 months, repaired CHD with residual defects, or prior history of endocarditis. (AHA Guidelines/Nelson)'),
    (v_topic_id, '89: A 2-month-old presents with 5 days of fever, bilateral non-exudative conjunctivitis, strawberry tongue, cervical lymphadenopathy, and a polymorphous rash. What is the most critical cardiac complication to prevent?', '["Aortic dissection", "Ventricular septal rupture", "Rheumatic mitral stenosis", "Coronary artery aneurysms"]', 3, 'This is classic Kawasaki disease. The primary goal of treatment with IVIG and aspirin is to prevent the development of coronary artery aneurysms. (Nelson Essentials)'),
    (v_topic_id, '90: A 1-year-old immigrant presents with a history of recurrent sore throats and now has a new, rumbling diastolic murmur at the apex with an opening snap. What is the most likely diagnosis?', '["Rheumatic mitral stenosis", "Congenital aortic stenosis", "Ventricular Septal Defect", "Infective endocarditis"]', 0, 'A rumbling diastolic murmur with an opening snap is classic for mitral stenosis, which is almost always a late consequence of Rheumatic Heart Disease following Group A Strep pharyngitis. (Blueprints)'),
    (v_topic_id, '91: A 4-year-old female toddler is evaluated for a murmur. A harsh, holosystolic murmur is heard best at the left lower sternal border. The child is asymptomatic and growing well. What is the most likely diagnosis?', '["Atrial Septal Defect (ASD)", "Ventricular Septal Defect (VSD)", "Coarctation of the Aorta", "Patent Ductus Arteriosus (PDA)"]', 1, 'VSD is the most common congenital heart defect, presenting with a harsh, holosystolic murmur at the left lower sternal border. Small VSDs are asymptomatic. (Nelson Essentials)'),
    (v_topic_id, '92: A 2-week-old male toddler with a known large VSD presents with tachypnea, diaphoresis during feeds, and poor weight gain. What is the most appropriate initial medical therapy?', '["Immediate surgical closure", "Prostaglandin E1", "Indomethacin", "Diuretics (e.g., Furosemide) and high-calorie formula"]', 3, 'Infants with large VSDs and heart failure are initially managed medically with diuretics and nutritional support to allow for growth before surgical repair. (Nelson Essentials)'),
    (v_topic_id, '93: In a patient with a Ventricular Septal Defect, the development of pulmonary hypertension and reversal of the shunt (right-to-left) leading to cyanosis is known as:', '["Tetralogy of Fallot", "Cor pulmonale", "Ebstein anomaly", "Eisenmenger syndrome"]', 3, 'Eisenmenger syndrome occurs when chronic left-to-right shunting causes pulmonary vascular disease, eventually reversing the shunt and causing cyanosis. (Blueprints)'),
    (v_topic_id, '94: Which of the following describes the typical natural history of a small, restrictive Ventricular Septal Defect?', '["Development of Eisenmenger syndrome", "Progression to heart failure", "High risk of sudden cardiac death", "Spontaneous closure in childhood"]', 3, 'The majority of small, muscular VSDs close spontaneously during childhood and do not require surgical intervention. (BRS Pediatrics)'),
    (v_topic_id, '95: A 2-week-old female toddler has a holosystolic murmur at the left lower sternal border. An echocardiogram shows a large VSD. Which of the following chamber enlargements is most likely?', '["Right ventricle only", "Right atrium and Right ventricle", "Left atrium only", "Left atrium and Left ventricle"]', 3, 'A large VSD causes a left-to-right shunt. The extra blood goes to the lungs and returns to the left heart, causing LA and LV volume overload and dilation. (Nelson Essentials)'),
    (v_topic_id, '96: A 3-year-old girl is found to have a widely split and fixed S2 on routine examination. There is also a soft systolic ejection murmur at the left upper sternal border. What is the most likely diagnosis?', '["Pulmonary Stenosis", "Atrial Septal Defect (ASD)", "Ventricular Septal Defect (VSD)", "Tetralogy of Fallot"]', 1, 'A widely split and fixed S2 is the hallmark of an ASD. The systolic murmur is due to increased flow across the pulmonary valve. (Case Files Pediatrics)'),
    (v_topic_id, '97: An ostium primum Atrial Septal Defect is most commonly associated with which genetic syndrome?', '["DiGeorge syndrome", "Turner syndrome", "Down syndrome (Trisomy 21)", "Marfan syndrome"]', 2, 'Ostium primum ASDs and Atrioventricular Septal Defects (AVSDs) are highly associated with Down syndrome. (Blueprints)'),
    (v_topic_id, '98: What is the primary hemodynamic consequence of an unrepaired moderate-to-large Atrial Septal Defect over decades?', '["Left ventricular hypertrophy", "Premature coronary artery disease", "Right-sided heart volume overload and failure", "Aortic root dilation"]', 2, 'Chronic left-to-right shunting through an ASD leads to right atrial and right ventricular volume overload, eventually causing right heart failure or arrhythmias in adulthood. (BRS Pediatrics)'),
    (v_topic_id, '99: A 1-year-old boy with an unrepaired ASD presents with a sudden onset stroke. What is the most likely mechanism?', '["Paradoxical embolus", "Infective endocarditis", "Atherosclerotic plaque rupture", "Hemorrhage from a berry aneurysm"]', 0, 'A venous thrombus can cross through the ASD (right-to-left shunting during transient pressure changes) into the systemic circulation, causing a paradoxical embolus and stroke. (Nelson Essentials)'),
    (v_topic_id, '100: Which type of Atrial Septal Defect is the most common?', '["Coronary sinus", "Ostium primum", "Sinus venosus", "Ostium secundum"]', 3, 'The ostium secundum defect, located in the central portion of the atrial septum, is the most common type of ASD. (Blueprints)'),
    (v_topic_id, '101: A 3-month-old premature infant has a continuous, machine-like murmur heard best at the left infraclavicular area. Bounding peripheral pulses are noted. What is the most likely diagnosis?', '["Coarctation of the Aorta", "Truncus Arteriosus", "Patent Ductus Arteriosus (PDA)", "Aortic Regurgitation"]', 2, 'A continuous machine-like murmur and bounding pulses (due to widened pulse pressure) are classic findings of a Patent Ductus Arteriosus. (Nelson Essentials)'),
    (v_topic_id, '102: What medication is used to induce closure of a Patent Ductus Arteriosus in a premature infant?', '["Prostaglandin E1", "Spironolactone", "Indomethacin (or Ibuprofen)", "Acetaminophen"]', 2, 'NSAIDs like indomethacin or ibuprofen inhibit prostaglandin synthesis, which promotes the closure of the ductus arteriosus. (BRS Pediatrics)'),
    (v_topic_id, '103: In which of the following congenital heart defects is a Patent Ductus Arteriosus essential for survival (ductal-dependent)?', '["Atrial Septal Defect", "Transposition of the Great Arteries", "Mild Pulmonary Stenosis", "Small Ventricular Septal Defect"]', 1, 'In Transposition of the Great Arteries, mixing of oxygenated and deoxygenated blood is required for survival, making it a ductal-dependent lesion. (Case Files Pediatrics)'),
    (v_topic_id, '104: Maternal infection with which organism during the first trimester is classically associated with Patent Ductus Arteriosus?', '["Herpes Simplex Virus", "Toxoplasma gondii", "Cytomegalovirus", "Rubella"]', 3, 'Congenital rubella syndrome is classically associated with cataracts, sensorineural hearing loss, and congenital heart defects, most notably PDA and pulmonary artery stenosis. (Nelson Essentials)'),
    (v_topic_id, '105: Which medication is administered to maintain the patency of the ductus arteriosus in a newborn with ductal-dependent congenital heart disease?', '["Milrinone", "Epinephrine", "Indomethacin", "Prostaglandin E1 (Alprostadil)"]', 3, 'Prostaglandin E1 is used to keep the ductus arteriosus open until surgical intervention can be performed in ductal-dependent lesions. (Blueprints)'),
    (v_topic_id, '106: A 4-month-old female infant is found to have hypertension in the upper extremities and diminished, delayed femoral pulses. What is the most likely diagnosis?', '["Patent Ductus Arteriosus", "Renal Artery Stenosis", "Coarctation of the Aorta", "Aortic Stenosis"]', 2, 'Coarctation of the aorta presents with a blood pressure discrepancy between the upper and lower extremities and decreased or delayed femoral pulses. (Nelson Essentials)'),
    (v_topic_id, '107: Which genetic syndrome has a high association with Coarctation of the Aorta?', '["Turner syndrome", "Marfan syndrome", "Down syndrome", "DiGeorge syndrome"]', 0, 'Turner syndrome (45,X) is strongly associated with left-sided heart lesions, particularly coarctation of the aorta and bicuspid aortic valve. (BRS Pediatrics)'),
    (v_topic_id, '108: A chest X-ray of an older child with undiagnosed Coarctation of the Aorta is most likely to show:', '["Snowman sign", "Rib notching and a ''''figure 3'''' sign", "Egg on a string appearance", "Boot-shaped heart"]', 1, 'Rib notching is caused by enlarged collateral intercostal arteries. The ''figure 3'' sign is formed by the pre-stenotic dilation, the coarctation itself, and the post-stenotic dilation. (Case Files Pediatrics)'),
    (v_topic_id, '109: Coarctation of the Aorta is most commonly associated with which other congenital cardiac anomaly?', '["Ebstein anomaly", "Bicuspid aortic valve", "Mitral valve prolapse", "Pulmonary atresia"]', 1, 'Up to 85% of patients with coarctation of the aorta also have a bicuspid aortic valve. (Blueprints)'),
    (v_topic_id, '110: A neonate with critical Coarctation of the Aorta presents with sudden shock and severe acidosis on day 3 of life. What is the immediate life-saving intervention?', '["Intravenous Prostaglandin E1", "Immediate heart transplant", "Intravenous Indomethacin", "Intravenous fluid bolus alone"]', 0, 'In critical coarctation, lower body perfusion is ductal-dependent. Closure of the PDA leads to shock. PGE1 reopens the ductus. (Nelson Essentials)'),
    (v_topic_id, '111: A 3-year-old female toddler presents with cyanosis during episodes of crying or feeding. The cyanosis improves when the child is placed in a knee-chest position. What is the most likely diagnosis?', '["Tetralogy of Fallot", "Truncus Arteriosus", "Transposition of the Great Arteries", "Tricuspid Atresia"]', 0, 'These ''tet spells'' are characteristic of Tetralogy of Fallot. The knee-chest position increases systemic vascular resistance, decreasing the right-to-left shunt and improving pulmonary blood flow. (Nelson Essentials)'),
    (v_topic_id, '112: Which of the following is NOT one of the four classic components of Tetralogy of Fallot?', '["Pulmonary Stenosis", "Right Ventricular Hypertrophy", "Ventricular Septal Defect", "Atrial Septal Defect"]', 3, 'The components (PROVe) are Pulmonary stenosis (RV outflow tract obstruction), Right ventricular hypertrophy, Overriding aorta, and VSD. (BRS Pediatrics)'),
    (v_topic_id, '113: What is the classic chest X-ray finding in a patient with Tetralogy of Fallot?', '["Snowman sign", "Figure 3 sign", "Egg on a string", "Boot-shaped heart (Coeur en sabot)"]', 3, 'The boot-shaped heart is due to right ventricular hypertrophy (upturned apex) and a concave main pulmonary artery segment. (Case Files Pediatrics)'),
    (v_topic_id, '114: In Tetralogy of Fallot, the degree of cyanosis and clinical severity is most primarily determined by the severity of:', '["The size of the VSD", "Right ventricular outflow tract obstruction (Pulmonary stenosis)", "The amount of right ventricular hypertrophy", "The degree of aortic override"]', 1, 'The severity of pulmonary stenosis dictates the amount of right-to-left shunting across the VSD, which determines the degree of cyanosis. (Blueprints)'),
    (v_topic_id, '115: A 2-month-old with Tetralogy of Fallot presents with an acute hypercyanotic spell (Tet spell). After placing the child in a knee-chest position, which medication is most appropriate to administer?', '["Digoxin", "Epinephrine", "Diuretics", "Morphine and Oxygen"]', 3, 'Management of a Tet spell includes knee-chest position, oxygen, morphine (decreases sympathetic drive and infundibular spasm), and IV fluids. Beta-blockers or phenylephrine can also be used. (Nelson Essentials)'),
    (v_topic_id, '116: A neonate presents with profound cyanosis immediately after birth. Echocardiogram reveals that the aorta arises from the right ventricle and the pulmonary artery from the left ventricle. What is the diagnosis?', '["Tetralogy of Fallot", "Total Anomalous Pulmonary Venous Return", "Transposition of the Great Arteries (TGA)", "Truncus Arteriosus"]', 2, 'TGA is the most common cyanotic heart defect presenting in the immediate newborn period. It creates two parallel circulatory systems. (Nelson Essentials)'),
    (v_topic_id, '117: In a newborn with Transposition of the Great Arteries, survival before surgical repair depends entirely on:', '["Mixing of blood via a PDA, ASD, or VSD", "Administration of 100% oxygen", "Keeping the infant in a knee-chest position", "Administering Indomethacin"]', 0, 'Because the pulmonary and systemic circulations are in parallel, life is impossible without mixing of oxygenated and deoxygenated blood through a shunt (PDA, PFO/ASD, or VSD). (Blueprints)'),
    (v_topic_id, '118: What is the classic chest X-ray appearance in a neonate with Transposition of the Great Arteries?', '["''Egg on a string'' with a narrow mediastinum", "Boot-shaped heart", "Wall-to-wall heart", "Snowman sign"]', 0, 'The ''egg on a string'' appearance is due to the anteroposterior relationship of the great vessels (causing a narrow superior mediastinum) and a globular heart. (BRS Pediatrics)'),
    (v_topic_id, '119: If Prostaglandin E1 fails to improve oxygenation in a severely cyanotic neonate with Transposition of the Great Arteries, what is the next best step?', '["Administration of Indomethacin", "Immediate open-heart surgery", "High-frequency oscillatory ventilation", "Balloon atrial septostomy (Rashkind procedure)"]', 3, 'If the PFO is restrictive and PGE1 isn''t enough, a balloon atrial septostomy is performed via catheterization to tear the atrial septum and improve mixing. (Case Files Pediatrics)'),
    (v_topic_id, '120: Transposition of the Great Arteries is strongly associated with which maternal condition?', '["Maternal lithium use", "Maternal rubella infection", "Maternal diabetes mellitus", "Maternal lupus"]', 2, 'Infants of diabetic mothers have a significantly increased risk of congenital heart defects, including TGA, VSD, and hypertrophic cardiomyopathy. (Nelson Essentials)'),
    (v_topic_id, '121: A neonate is found to have a single large vessel arising from the base of the heart that gives rise to the coronary, pulmonary, and systemic arteries. A VSD is also present. Diagnosis?', '["Transposition of the Great Arteries", "Truncus Arteriosus", "Tetralogy of Fallot", "Tricuspid Atresia"]', 1, 'Truncus arteriosus involves failure of the conotruncal septum to form, resulting in a single great vessel and a mandatory VSD. (Blueprints)'),
    (v_topic_id, '122: Truncus Arteriosus and Tetralogy of Fallot are frequently associated with microdeletion of chromosome 22q11. What syndrome is this?', '["Turner syndrome", "Down syndrome", "DiGeorge syndrome", "Williams syndrome"]', 2, 'DiGeorge syndrome (22q11.2 deletion) is associated with conotruncal cardiac defects (Truncus, ToF), abnormal facies, thymic hypoplasia, cleft palate, and hypocalcemia. (Nelson Essentials)'),
    (v_topic_id, '123: A cyanotic newborn has an ECG showing Left Axis Deviation and Left Ventricular Hypertrophy (LVH). Right ventricular forces are completely absent. What is the most likely diagnosis?', '["Tetralogy of Fallot", "Tricuspid Atresia", "Transposition of the Great Arteries", "Pulmonary Stenosis"]', 1, 'Most cyanotic congenital heart defects present with Right Axis Deviation and RVH. Tricuspid Atresia is unique as it causes hypoplasia of the RV, leading to LAD and LVH. (Case Files Pediatrics)'),
    (v_topic_id, '124: For an infant with Tricuspid Atresia to survive, blood must bypass the right atrium. What obligatory defect must be present?', '["Pulmonary Atresia", "Atrial Septal Defect (ASD) or Patent Foramen Ovale (PFO)", "Coarctation of the Aorta", "Aortic Stenosis"]', 1, 'Since the tricuspid valve is absent, all systemic venous blood must cross the atrial septum (via ASD/PFO) to the left atrium to reach the left ventricle. (Blueprints)'),
    (v_topic_id, '125: A neonate with cyanosis has a chest X-ray demonstrating a ''snowman'' (or figure-8) appearance of the cardiac silhouette. What is the diagnosis?', '["Transposition of the Great Arteries", "Total Anomalous Pulmonary Venous Return (TAPVR)", "Tetralogy of Fallot", "Coarctation of the Aorta"]', 1, 'In TAPVR, all pulmonary veins drain into the systemic venous circulation (e.g., SVC). The dilated vertical vein and SVC above the heart create the ''head'' of the snowman. (Nelson Essentials)'),
    (v_topic_id, '126: A neonate presents with cyanosis. Echocardiogram shows downward displacement of the tricuspid valve leaflets into the right ventricle, causing ''atrialization'' of the right ventricle. Diagnosis?', '["Tetralogy of Fallot", "Truncus Arteriosus", "Ebstein Anomaly", "Tricuspid Atresia"]', 2, 'Ebstein anomaly is characterized by apical displacement of the tricuspid valve, leading to a small functional RV and severe tricuspid regurgitation. (Blueprints)'),
    (v_topic_id, '127: Maternal use of which psychiatric medication during pregnancy is classically associated with Ebstein Anomaly?', '["SSRI (e.g., Fluoxetine)", "Valproic acid", "Carbamazepine", "Lithium"]', 3, 'Lithium exposure in the first trimester is classically linked to a higher risk of Ebstein anomaly. (BRS Pediatrics)'),
    (v_topic_id, '128: Patients with Ebstein Anomaly have a high incidence of which cardiac arrhythmia?', '["Torsades de pointes", "Ventricular Fibrillation", "First-degree AV block", "Wolff-Parkinson-White (WPW) syndrome"]', 3, 'Ebstein anomaly is strongly associated with accessory conduction pathways, leading to WPW syndrome and supraventricular tachycardias. (Nelson Essentials)'),
    (v_topic_id, '129: A 2-year-old newborn presents with shock, weak pulses, and gray cyanosis shortly after the ductus arteriosus begins to close. Echocardiogram shows a severely underdeveloped left ventricle. Diagnosis?', '["Tetralogy of Fallot", "Hypoplastic Left Heart Syndrome (HLHS)", "Ebstein Anomaly", "Tricuspid Atresia"]', 1, 'HLHS involves hypoplasia of the left ventricle, mitral valve, and aorta. Systemic blood flow is entirely dependent on a Patent Ductus Arteriosus (PDA). (Case Files Pediatrics)'),
    (v_topic_id, '130: What is the primary staged surgical palliation pathway for Hypoplastic Left Heart Syndrome (HLHS)?', '["Norwood procedure, followed by Glenn, then Fontan", "Ross procedure", "Blalock-Taussig shunt alone", "Arterial switch operation"]', 0, 'The Norwood procedure (stage 1) constructs a new aorta, followed by the bidirectional Glenn (stage 2), and the Fontan completion (stage 3) to route venous return directly to the lungs. (Nelson Essentials)'),
    (v_topic_id, '131: Which of the following is an acyanotic congenital heart defect?', '["Ventricular Septal Defect", "Tetralogy of Fallot", "Transposition of the Great Arteries", "Truncus Arteriosus"]', 0, 'VSD, ASD, and PDA are left-to-right shunts, which are acyanotic. The ''5 Ts'' (ToF, TGA, Truncus, Tricuspid Atresia, TAPVR) are right-to-left shunts and are cyanotic. (Blueprints)'),
    (v_topic_id, '132: The ''5 Ts'' of cyanotic congenital heart disease include all EXCEPT:', '["Tetralogy of Fallot", "Transposition of the Great Arteries", "Truncus Arteriosus", "Tachycardia induced cardiomyopathy"]', 3, 'The 5 Ts are Tetralogy, Transposition, Truncus, Tricuspid Atresia, and TAPVR. (BRS Pediatrics)'),
    (v_topic_id, '133: Which of the following patients requires antibiotic prophylaxis prior to a dental procedure?', '["A child with an isolated, repaired ASD (surgery 2 years ago)", "A child with a history of Kawasaki disease without aneurysms", "A child with a physiologic flow murmur", "A child with an unrepaired cyanotic congenital heart defect"]', 3, 'Endocarditis prophylaxis is recommended for unrepaired cyanotic CHD, completely repaired CHD within the first 6 months, repaired CHD with residual defects, or prior history of endocarditis. (AHA Guidelines/Nelson)'),
    (v_topic_id, '134: A 2-week-old presents with 5 days of fever, bilateral non-exudative conjunctivitis, strawberry tongue, cervical lymphadenopathy, and a polymorphous rash. What is the most critical cardiac complication to prevent?', '["Aortic dissection", "Rheumatic mitral stenosis", "Coronary artery aneurysms", "Ventricular septal rupture"]', 2, 'This is classic Kawasaki disease. The primary goal of treatment with IVIG and aspirin is to prevent the development of coronary artery aneurysms. (Nelson Essentials)'),
    (v_topic_id, '135: A 1-year-old immigrant presents with a history of recurrent sore throats and now has a new, rumbling diastolic murmur at the apex with an opening snap. What is the most likely diagnosis?', '["Infective endocarditis", "Congenital aortic stenosis", "Rheumatic mitral stenosis", "Ventricular Septal Defect"]', 2, 'A rumbling diastolic murmur with an opening snap is classic for mitral stenosis, which is almost always a late consequence of Rheumatic Heart Disease following Group A Strep pharyngitis. (Blueprints)'),
    (v_topic_id, '136: A 2-week-old girl is evaluated for a murmur. A harsh, holosystolic murmur is heard best at the parasternal border. The child is asymptomatic and growing well. What is the most likely diagnosis?', '["Coarctation of the Aorta", "Atrial Septal Defect (ASD)", "Patent Ductus Arteriosus (PDA)", "Ventricular Septal Defect (VSD)"]', 3, 'VSD is the most common congenital heart defect, presenting with a harsh, holosystolic murmur at the left lower sternal border. Small VSDs are asymptomatic. (Nelson Essentials)'),
    (v_topic_id, '137: A 1-day-old girl with a known large VSD presents with tachypnea, diaphoresis during feeds, and poor weight gain. What is the most appropriate initial medical therapy?', '["Immediate surgical closure", "Prostaglandin E1", "Indomethacin", "Diuretics (e.g., Furosemide) and high-calorie formula"]', 3, 'Infants with large VSDs and heart failure are initially managed medically with diuretics and nutritional support to allow for growth before surgical repair. (Nelson Essentials)'),
    (v_topic_id, '138: In a patient with a Ventricular Septal Defect, the development of pulmonary hypertension and reversal of the shunt (right-to-left) leading to cyanosis is known as:', '["Eisenmenger syndrome", "Tetralogy of Fallot", "Ebstein anomaly", "Cor pulmonale"]', 0, 'Eisenmenger syndrome occurs when chronic left-to-right shunting causes pulmonary vascular disease, eventually reversing the shunt and causing cyanosis. (Blueprints)'),
    (v_topic_id, '139: Which of the following describes the typical natural history of a small, restrictive Ventricular Septal Defect?', '["Spontaneous closure in childhood", "Development of Eisenmenger syndrome", "High risk of sudden cardiac death", "Progression to heart failure"]', 0, 'The majority of small, muscular VSDs close spontaneously during childhood and do not require surgical intervention. (BRS Pediatrics)'),
    (v_topic_id, '140: A 4-month-old girl has a holosystolic murmur at the left lower sternal border. An echocardiogram shows a large VSD. Which of the following chamber enlargements is most likely?', '["Left atrium only", "Right atrium and Right ventricle", "Right ventricle only", "Left atrium and Left ventricle"]', 3, 'A large VSD causes a left-to-right shunt. The extra blood goes to the lungs and returns to the left heart, causing LA and LV volume overload and dilation. (Nelson Essentials)'),
    (v_topic_id, '141: A 6-month-old boy is found to have a widely split and fixed S2 on routine examination. There is also a soft systolic ejection murmur at the left upper sternal border. What is the most likely diagnosis?', '["Tetralogy of Fallot", "Ventricular Septal Defect (VSD)", "Pulmonary Stenosis", "Atrial Septal Defect (ASD)"]', 3, 'A widely split and fixed S2 is the hallmark of an ASD. The systolic murmur is due to increased flow across the pulmonary valve. (Case Files Pediatrics)'),
    (v_topic_id, '142: An ostium primum Atrial Septal Defect is most commonly associated with which genetic syndrome?', '["DiGeorge syndrome", "Turner syndrome", "Down syndrome (Trisomy 21)", "Marfan syndrome"]', 2, 'Ostium primum ASDs and Atrioventricular Septal Defects (AVSDs) are highly associated with Down syndrome. (Blueprints)'),
    (v_topic_id, '143: What is the primary hemodynamic consequence of an unrepaired moderate-to-large Atrial Septal Defect over decades?', '["Aortic root dilation", "Left ventricular hypertrophy", "Right-sided heart volume overload and failure", "Premature coronary artery disease"]', 2, 'Chronic left-to-right shunting through an ASD leads to right atrial and right ventricular volume overload, eventually causing right heart failure or arrhythmias in adulthood. (BRS Pediatrics)'),
    (v_topic_id, '144: A 1-year-old girl with an unrepaired ASD presents with a sudden onset stroke. What is the most likely mechanism?', '["Atherosclerotic plaque rupture", "Infective endocarditis", "Paradoxical embolus", "Hemorrhage from a berry aneurysm"]', 2, 'A venous thrombus can cross through the ASD (right-to-left shunting during transient pressure changes) into the systemic circulation, causing a paradoxical embolus and stroke. (Nelson Essentials)'),
    (v_topic_id, '145: Which type of Atrial Septal Defect is the most common?', '["Ostium primum", "Sinus venosus", "Coronary sinus", "Ostium secundum"]', 3, 'The ostium secundum defect, located in the central portion of the atrial septum, is the most common type of ASD. (Blueprints)'),
    (v_topic_id, '146: A 2-year-old premature infant has a continuous, machine-like murmur heard best at the left infraclavicular area. Bounding peripheral pulses are noted. What is the most likely diagnosis?', '["Patent Ductus Arteriosus (PDA)", "Truncus Arteriosus", "Aortic Regurgitation", "Coarctation of the Aorta"]', 0, 'A continuous machine-like murmur and bounding pulses (due to widened pulse pressure) are classic findings of a Patent Ductus Arteriosus. (Nelson Essentials)'),
    (v_topic_id, '147: What medication is used to induce closure of a Patent Ductus Arteriosus in a premature infant?', '["Prostaglandin E1", "Spironolactone", "Acetaminophen", "Indomethacin (or Ibuprofen)"]', 3, 'NSAIDs like indomethacin or ibuprofen inhibit prostaglandin synthesis, which promotes the closure of the ductus arteriosus. (BRS Pediatrics)'),
    (v_topic_id, '148: In which of the following congenital heart defects is a Patent Ductus Arteriosus essential for survival (ductal-dependent)?', '["Mild Pulmonary Stenosis", "Small Ventricular Septal Defect", "Atrial Septal Defect", "Transposition of the Great Arteries"]', 3, 'In Transposition of the Great Arteries, mixing of oxygenated and deoxygenated blood is required for survival, making it a ductal-dependent lesion. (Case Files Pediatrics)'),
    (v_topic_id, '149: Maternal infection with which organism during the first trimester is classically associated with Patent Ductus Arteriosus?', '["Cytomegalovirus", "Herpes Simplex Virus", "Rubella", "Toxoplasma gondii"]', 2, 'Congenital rubella syndrome is classically associated with cataracts, sensorineural hearing loss, and congenital heart defects, most notably PDA and pulmonary artery stenosis. (Nelson Essentials)'),
    (v_topic_id, '150: Which medication is administered to maintain the patency of the ductus arteriosus in a newborn with ductal-dependent congenital heart disease?', '["Prostaglandin E1 (Alprostadil)", "Milrinone", "Indomethacin", "Epinephrine"]', 0, 'Prostaglandin E1 is used to keep the ductus arteriosus open until surgical intervention can be performed in ductal-dependent lesions. (Blueprints)'),
    (v_topic_id, '151: A 1-day-old male infant is found to have hypertension in the upper extremities and diminished, delayed femoral pulses. What is the most likely diagnosis?', '["Patent Ductus Arteriosus", "Coarctation of the Aorta", "Renal Artery Stenosis", "Aortic Stenosis"]', 1, 'Coarctation of the aorta presents with a blood pressure discrepancy between the upper and lower extremities and decreased or delayed femoral pulses. (Nelson Essentials)'),
    (v_topic_id, '152: Which genetic syndrome has a high association with Coarctation of the Aorta?', '["Down syndrome", "Marfan syndrome", "Turner syndrome", "DiGeorge syndrome"]', 2, 'Turner syndrome (45,X) is strongly associated with left-sided heart lesions, particularly coarctation of the aorta and bicuspid aortic valve. (BRS Pediatrics)'),
    (v_topic_id, '153: A chest X-ray of an older child with undiagnosed Coarctation of the Aorta is most likely to show:', '["Egg on a string appearance", "Boot-shaped heart", "Rib notching and a ''''figure 3'''' sign", "Snowman sign"]', 2, 'Rib notching is caused by enlarged collateral intercostal arteries. The ''figure 3'' sign is formed by the pre-stenotic dilation, the coarctation itself, and the post-stenotic dilation. (Case Files Pediatrics)'),
    (v_topic_id, '154: Coarctation of the Aorta is most commonly associated with which other congenital cardiac anomaly?', '["Ebstein anomaly", "Bicuspid aortic valve", "Mitral valve prolapse", "Pulmonary atresia"]', 1, 'Up to 85% of patients with coarctation of the aorta also have a bicuspid aortic valve. (Blueprints)'),
    (v_topic_id, '155: A neonate with critical Coarctation of the Aorta presents with sudden shock and severe acidosis on day 3 of life. What is the immediate life-saving intervention?', '["Intravenous fluid bolus alone", "Immediate heart transplant", "Intravenous Prostaglandin E1", "Intravenous Indomethacin"]', 2, 'In critical coarctation, lower body perfusion is ductal-dependent. Closure of the PDA leads to shock. PGE1 reopens the ductus. (Nelson Essentials)'),
    (v_topic_id, '156: A 3-month-old boy presents with cyanosis during episodes of crying or feeding. The cyanosis improves when the child is placed in a knee-chest position. What is the most likely diagnosis?', '["Transposition of the Great Arteries", "Tetralogy of Fallot", "Truncus Arteriosus", "Tricuspid Atresia"]', 1, 'These ''tet spells'' are characteristic of Tetralogy of Fallot. The knee-chest position increases systemic vascular resistance, decreasing the right-to-left shunt and improving pulmonary blood flow. (Nelson Essentials)'),
    (v_topic_id, '157: Which of the following is NOT one of the four classic components of Tetralogy of Fallot?', '["Atrial Septal Defect", "Right Ventricular Hypertrophy", "Pulmonary Stenosis", "Ventricular Septal Defect"]', 0, 'The components (PROVe) are Pulmonary stenosis (RV outflow tract obstruction), Right ventricular hypertrophy, Overriding aorta, and VSD. (BRS Pediatrics)'),
    (v_topic_id, '158: What is the classic chest X-ray finding in a patient with Tetralogy of Fallot?', '["Snowman sign", "Figure 3 sign", "Egg on a string", "Boot-shaped heart (Coeur en sabot)"]', 3, 'The boot-shaped heart is due to right ventricular hypertrophy (upturned apex) and a concave main pulmonary artery segment. (Case Files Pediatrics)'),
    (v_topic_id, '159: In Tetralogy of Fallot, the degree of cyanosis and clinical severity is most primarily determined by the severity of:', '["The size of the VSD", "Right ventricular outflow tract obstruction (Pulmonary stenosis)", "The amount of right ventricular hypertrophy", "The degree of aortic override"]', 1, 'The severity of pulmonary stenosis dictates the amount of right-to-left shunting across the VSD, which determines the degree of cyanosis. (Blueprints)'),
    (v_topic_id, '160: A 3-month-old with Tetralogy of Fallot presents with an acute hypercyanotic spell (Tet spell). After placing the child in a knee-chest position, which medication is most appropriate to administer?', '["Diuretics", "Digoxin", "Epinephrine", "Morphine and Oxygen"]', 3, 'Management of a Tet spell includes knee-chest position, oxygen, morphine (decreases sympathetic drive and infundibular spasm), and IV fluids. Beta-blockers or phenylephrine can also be used. (Nelson Essentials)'),
    (v_topic_id, '161: A neonate presents with profound cyanosis immediately after birth. Echocardiogram reveals that the aorta arises from the right ventricle and the pulmonary artery from the left ventricle. What is the diagnosis?', '["Tetralogy of Fallot", "Truncus Arteriosus", "Transposition of the Great Arteries (TGA)", "Total Anomalous Pulmonary Venous Return"]', 2, 'TGA is the most common cyanotic heart defect presenting in the immediate newborn period. It creates two parallel circulatory systems. (Nelson Essentials)'),
    (v_topic_id, '162: In a newborn with Transposition of the Great Arteries, survival before surgical repair depends entirely on:', '["Keeping the infant in a knee-chest position", "Mixing of blood via a PDA, ASD, or VSD", "Administering Indomethacin", "Administration of 100% oxygen"]', 1, 'Because the pulmonary and systemic circulations are in parallel, life is impossible without mixing of oxygenated and deoxygenated blood through a shunt (PDA, PFO/ASD, or VSD). (Blueprints)'),
    (v_topic_id, '163: What is the classic chest X-ray appearance in a neonate with Transposition of the Great Arteries?', '["Snowman sign", "Boot-shaped heart", "Wall-to-wall heart", "''Egg on a string'' with a narrow mediastinum"]', 3, 'The ''egg on a string'' appearance is due to the anteroposterior relationship of the great vessels (causing a narrow superior mediastinum) and a globular heart. (BRS Pediatrics)'),
    (v_topic_id, '164: If Prostaglandin E1 fails to improve oxygenation in a severely cyanotic neonate with Transposition of the Great Arteries, what is the next best step?', '["High-frequency oscillatory ventilation", "Balloon atrial septostomy (Rashkind procedure)", "Administration of Indomethacin", "Immediate open-heart surgery"]', 1, 'If the PFO is restrictive and PGE1 isn''t enough, a balloon atrial septostomy is performed via catheterization to tear the atrial septum and improve mixing. (Case Files Pediatrics)'),
    (v_topic_id, '165: Transposition of the Great Arteries is strongly associated with which maternal condition?', '["Maternal rubella infection", "Maternal lithium use", "Maternal diabetes mellitus", "Maternal lupus"]', 2, 'Infants of diabetic mothers have a significantly increased risk of congenital heart defects, including TGA, VSD, and hypertrophic cardiomyopathy. (Nelson Essentials)'),
    (v_topic_id, '166: A neonate is found to have a single large vessel arising from the base of the heart that gives rise to the coronary, pulmonary, and systemic arteries. A VSD is also present. Diagnosis?', '["Tetralogy of Fallot", "Transposition of the Great Arteries", "Tricuspid Atresia", "Truncus Arteriosus"]', 3, 'Truncus arteriosus involves failure of the conotruncal septum to form, resulting in a single great vessel and a mandatory VSD. (Blueprints)'),
    (v_topic_id, '167: Truncus Arteriosus and Tetralogy of Fallot are frequently associated with microdeletion of chromosome 22q11. What syndrome is this?', '["DiGeorge syndrome", "Williams syndrome", "Down syndrome", "Turner syndrome"]', 0, 'DiGeorge syndrome (22q11.2 deletion) is associated with conotruncal cardiac defects (Truncus, ToF), abnormal facies, thymic hypoplasia, cleft palate, and hypocalcemia. (Nelson Essentials)'),
    (v_topic_id, '168: A cyanotic newborn has an ECG showing Left Axis Deviation and Left Ventricular Hypertrophy (LVH). Right ventricular forces are completely absent. What is the most likely diagnosis?', '["Pulmonary Stenosis", "Tetralogy of Fallot", "Tricuspid Atresia", "Transposition of the Great Arteries"]', 2, 'Most cyanotic congenital heart defects present with Right Axis Deviation and RVH. Tricuspid Atresia is unique as it causes hypoplasia of the RV, leading to LAD and LVH. (Case Files Pediatrics)'),
    (v_topic_id, '169: For an infant with Tricuspid Atresia to survive, blood must bypass the right atrium. What obligatory defect must be present?', '["Pulmonary Atresia", "Atrial Septal Defect (ASD) or Patent Foramen Ovale (PFO)", "Aortic Stenosis", "Coarctation of the Aorta"]', 1, 'Since the tricuspid valve is absent, all systemic venous blood must cross the atrial septum (via ASD/PFO) to the left atrium to reach the left ventricle. (Blueprints)'),
    (v_topic_id, '170: A neonate with cyanosis has a chest X-ray demonstrating a ''snowman'' (or figure-8) appearance of the cardiac silhouette. What is the diagnosis?', '["Total Anomalous Pulmonary Venous Return (TAPVR)", "Coarctation of the Aorta", "Transposition of the Great Arteries", "Tetralogy of Fallot"]', 0, 'In TAPVR, all pulmonary veins drain into the systemic venous circulation (e.g., SVC). The dilated vertical vein and SVC above the heart create the ''head'' of the snowman. (Nelson Essentials)'),
    (v_topic_id, '171: A neonate presents with cyanosis. Echocardiogram shows downward displacement of the tricuspid valve leaflets into the right ventricle, causing ''atrialization'' of the right ventricle. Diagnosis?', '["Ebstein Anomaly", "Truncus Arteriosus", "Tetralogy of Fallot", "Tricuspid Atresia"]', 0, 'Ebstein anomaly is characterized by apical displacement of the tricuspid valve, leading to a small functional RV and severe tricuspid regurgitation. (Blueprints)'),
    (v_topic_id, '172: Maternal use of which psychiatric medication during pregnancy is classically associated with Ebstein Anomaly?', '["Lithium", "Carbamazepine", "SSRI (e.g., Fluoxetine)", "Valproic acid"]', 0, 'Lithium exposure in the first trimester is classically linked to a higher risk of Ebstein anomaly. (BRS Pediatrics)'),
    (v_topic_id, '173: Patients with Ebstein Anomaly have a high incidence of which cardiac arrhythmia?', '["Wolff-Parkinson-White (WPW) syndrome", "Torsades de pointes", "Ventricular Fibrillation", "First-degree AV block"]', 0, 'Ebstein anomaly is strongly associated with accessory conduction pathways, leading to WPW syndrome and supraventricular tachycardias. (Nelson Essentials)'),
    (v_topic_id, '174: A 2-month-old newborn presents with shock, weak pulses, and gray cyanosis shortly after the ductus arteriosus begins to close. Echocardiogram shows a severely underdeveloped left ventricle. Diagnosis?', '["Tetralogy of Fallot", "Tricuspid Atresia", "Ebstein Anomaly", "Hypoplastic Left Heart Syndrome (HLHS)"]', 3, 'HLHS involves hypoplasia of the left ventricle, mitral valve, and aorta. Systemic blood flow is entirely dependent on a Patent Ductus Arteriosus (PDA). (Case Files Pediatrics)'),
    (v_topic_id, '175: What is the primary staged surgical palliation pathway for Hypoplastic Left Heart Syndrome (HLHS)?', '["Norwood procedure, followed by Glenn, then Fontan", "Arterial switch operation", "Blalock-Taussig shunt alone", "Ross procedure"]', 0, 'The Norwood procedure (stage 1) constructs a new aorta, followed by the bidirectional Glenn (stage 2), and the Fontan completion (stage 3) to route venous return directly to the lungs. (Nelson Essentials)'),
    (v_topic_id, '176: Which of the following is an acyanotic congenital heart defect?', '["Transposition of the Great Arteries", "Ventricular Septal Defect", "Tetralogy of Fallot", "Truncus Arteriosus"]', 1, 'VSD, ASD, and PDA are left-to-right shunts, which are acyanotic. The ''5 Ts'' (ToF, TGA, Truncus, Tricuspid Atresia, TAPVR) are right-to-left shunts and are cyanotic. (Blueprints)'),
    (v_topic_id, '177: The ''5 Ts'' of cyanotic congenital heart disease include all EXCEPT:', '["Tetralogy of Fallot", "Truncus Arteriosus", "Transposition of the Great Arteries", "Tachycardia induced cardiomyopathy"]', 3, 'The 5 Ts are Tetralogy, Transposition, Truncus, Tricuspid Atresia, and TAPVR. (BRS Pediatrics)'),
    (v_topic_id, '178: Which of the following patients requires antibiotic prophylaxis prior to a dental procedure?', '["A child with a history of Kawasaki disease without aneurysms", "A child with an unrepaired cyanotic congenital heart defect", "A child with a physiologic flow murmur", "A child with an isolated, repaired ASD (surgery 2 years ago)"]', 1, 'Endocarditis prophylaxis is recommended for unrepaired cyanotic CHD, completely repaired CHD within the first 6 months, repaired CHD with residual defects, or prior history of endocarditis. (AHA Guidelines/Nelson)'),
    (v_topic_id, '179: A 6-month-old presents with 5 days of fever, bilateral non-exudative conjunctivitis, strawberry tongue, cervical lymphadenopathy, and a polymorphous rash. What is the most critical cardiac complication to prevent?', '["Coronary artery aneurysms", "Ventricular septal rupture", "Aortic dissection", "Rheumatic mitral stenosis"]', 0, 'This is classic Kawasaki disease. The primary goal of treatment with IVIG and aspirin is to prevent the development of coronary artery aneurysms. (Nelson Essentials)'),
    (v_topic_id, '180: A 1-month-old immigrant presents with a history of recurrent sore throats and now has a new, rumbling diastolic murmur at the apex with an opening snap. What is the most likely diagnosis?', '["Rheumatic mitral stenosis", "Congenital aortic stenosis", "Ventricular Septal Defect", "Infective endocarditis"]', 0, 'A rumbling diastolic murmur with an opening snap is classic for mitral stenosis, which is almost always a late consequence of Rheumatic Heart Disease following Group A Strep pharyngitis. (Blueprints)'),
    (v_topic_id, '181: A 1-year-old boy is evaluated for a murmur. A harsh, holosystolic murmur is heard best at the parasternal border. The child is asymptomatic and growing well. What is the most likely diagnosis?', '["Atrial Septal Defect (ASD)", "Coarctation of the Aorta", "Patent Ductus Arteriosus (PDA)", "Ventricular Septal Defect (VSD)"]', 3, 'VSD is the most common congenital heart defect, presenting with a harsh, holosystolic murmur at the left lower sternal border. Small VSDs are asymptomatic. (Nelson Essentials)'),
    (v_topic_id, '182: A 6-month-old female infant with a known moderate VSD presents with tachypnea, diaphoresis during feeds, and poor weight gain. What is the most appropriate initial medical therapy?', '["Prostaglandin E1", "Indomethacin", "Diuretics (e.g., Furosemide) and high-calorie formula", "Immediate surgical closure"]', 2, 'Infants with large VSDs and heart failure are initially managed medically with diuretics and nutritional support to allow for growth before surgical repair. (Nelson Essentials)'),
    (v_topic_id, '183: In a patient with a Ventricular Septal Defect, the development of pulmonary hypertension and reversal of the shunt (right-to-left) leading to cyanosis is known as:', '["Tetralogy of Fallot", "Ebstein anomaly", "Cor pulmonale", "Eisenmenger syndrome"]', 3, 'Eisenmenger syndrome occurs when chronic left-to-right shunting causes pulmonary vascular disease, eventually reversing the shunt and causing cyanosis. (Blueprints)'),
    (v_topic_id, '184: Which of the following describes the typical natural history of a small, restrictive Ventricular Septal Defect?', '["Spontaneous closure in childhood", "High risk of sudden cardiac death", "Progression to heart failure", "Development of Eisenmenger syndrome"]', 0, 'The majority of small, muscular VSDs close spontaneously during childhood and do not require surgical intervention. (BRS Pediatrics)'),
    (v_topic_id, '185: A 3-month-old male infant has a holosystolic murmur at the left lower sternal border. An echocardiogram shows a large VSD. Which of the following chamber enlargements is most likely?', '["Right atrium and Right ventricle", "Left atrium and Left ventricle", "Right ventricle only", "Left atrium only"]', 1, 'A large VSD causes a left-to-right shunt. The extra blood goes to the lungs and returns to the left heart, causing LA and LV volume overload and dilation. (Nelson Essentials)'),
    (v_topic_id, '186: A 2-day-old male toddler is found to have a widely split and fixed S2 on routine examination. There is also a soft systolic ejection murmur at the left upper sternal border. What is the most likely diagnosis?', '["Tetralogy of Fallot", "Ventricular Septal Defect (VSD)", "Atrial Septal Defect (ASD)", "Pulmonary Stenosis"]', 2, 'A widely split and fixed S2 is the hallmark of an ASD. The systolic murmur is due to increased flow across the pulmonary valve. (Case Files Pediatrics)'),
    (v_topic_id, '187: An ostium primum Atrial Septal Defect is most commonly associated with which genetic syndrome?', '["Marfan syndrome", "DiGeorge syndrome", "Turner syndrome", "Down syndrome (Trisomy 21)"]', 3, 'Ostium primum ASDs and Atrioventricular Septal Defects (AVSDs) are highly associated with Down syndrome. (Blueprints)'),
    (v_topic_id, '188: What is the primary hemodynamic consequence of an unrepaired moderate-to-large Atrial Septal Defect over decades?', '["Aortic root dilation", "Premature coronary artery disease", "Left ventricular hypertrophy", "Right-sided heart volume overload and failure"]', 3, 'Chronic left-to-right shunting through an ASD leads to right atrial and right ventricular volume overload, eventually causing right heart failure or arrhythmias in adulthood. (BRS Pediatrics)'),
    (v_topic_id, '189: A 1-week-old male toddler with an unrepaired ASD presents with a sudden onset stroke. What is the most likely mechanism?', '["Atherosclerotic plaque rupture", "Hemorrhage from a berry aneurysm", "Paradoxical embolus", "Infective endocarditis"]', 2, 'A venous thrombus can cross through the ASD (right-to-left shunting during transient pressure changes) into the systemic circulation, causing a paradoxical embolus and stroke. (Nelson Essentials)'),
    (v_topic_id, '190: Which type of Atrial Septal Defect is the most common?', '["Sinus venosus", "Coronary sinus", "Ostium primum", "Ostium secundum"]', 3, 'The ostium secundum defect, located in the central portion of the atrial septum, is the most common type of ASD. (Blueprints)'),
    (v_topic_id, '191: A 4-year-old premature infant has a continuous, machine-like murmur heard best at the left infraclavicular area. Bounding peripheral pulses are noted. What is the most likely diagnosis?', '["Aortic Regurgitation", "Truncus Arteriosus", "Coarctation of the Aorta", "Patent Ductus Arteriosus (PDA)"]', 3, 'A continuous machine-like murmur and bounding pulses (due to widened pulse pressure) are classic findings of a Patent Ductus Arteriosus. (Nelson Essentials)'),
    (v_topic_id, '192: What medication is used to induce closure of a Patent Ductus Arteriosus in a premature infant?', '["Indomethacin (or Ibuprofen)", "Spironolactone", "Acetaminophen", "Prostaglandin E1"]', 0, 'NSAIDs like indomethacin or ibuprofen inhibit prostaglandin synthesis, which promotes the closure of the ductus arteriosus. (BRS Pediatrics)'),
    (v_topic_id, '193: In which of the following congenital heart defects is a Patent Ductus Arteriosus essential for survival (ductal-dependent)?', '["Transposition of the Great Arteries", "Mild Pulmonary Stenosis", "Atrial Septal Defect", "Small Ventricular Septal Defect"]', 0, 'In Transposition of the Great Arteries, mixing of oxygenated and deoxygenated blood is required for survival, making it a ductal-dependent lesion. (Case Files Pediatrics)'),
    (v_topic_id, '194: Maternal infection with which organism during the first trimester is classically associated with Patent Ductus Arteriosus?', '["Rubella", "Cytomegalovirus", "Toxoplasma gondii", "Herpes Simplex Virus"]', 0, 'Congenital rubella syndrome is classically associated with cataracts, sensorineural hearing loss, and congenital heart defects, most notably PDA and pulmonary artery stenosis. (Nelson Essentials)'),
    (v_topic_id, '195: Which medication is administered to maintain the patency of the ductus arteriosus in a newborn with ductal-dependent congenital heart disease?', '["Prostaglandin E1 (Alprostadil)", "Indomethacin", "Epinephrine", "Milrinone"]', 0, 'Prostaglandin E1 is used to keep the ductus arteriosus open until surgical intervention can be performed in ductal-dependent lesions. (Blueprints)'),
    (v_topic_id, '196: A 1-year-old boy is found to have hypertension in the upper extremities and diminished, delayed femoral pulses. What is the most likely diagnosis?', '["Patent Ductus Arteriosus", "Renal Artery Stenosis", "Coarctation of the Aorta", "Aortic Stenosis"]', 2, 'Coarctation of the aorta presents with a blood pressure discrepancy between the upper and lower extremities and decreased or delayed femoral pulses. (Nelson Essentials)'),
    (v_topic_id, '197: Which genetic syndrome has a high association with Coarctation of the Aorta?', '["Turner syndrome", "Marfan syndrome", "DiGeorge syndrome", "Down syndrome"]', 0, 'Turner syndrome (45,X) is strongly associated with left-sided heart lesions, particularly coarctation of the aorta and bicuspid aortic valve. (BRS Pediatrics)'),
    (v_topic_id, '198: A chest X-ray of an older child with undiagnosed Coarctation of the Aorta is most likely to show:', '["Egg on a string appearance", "Boot-shaped heart", "Snowman sign", "Rib notching and a ''''figure 3'''' sign"]', 3, 'Rib notching is caused by enlarged collateral intercostal arteries. The ''figure 3'' sign is formed by the pre-stenotic dilation, the coarctation itself, and the post-stenotic dilation. (Case Files Pediatrics)'),
    (v_topic_id, '199: Coarctation of the Aorta is most commonly associated with which other congenital cardiac anomaly?', '["Pulmonary atresia", "Bicuspid aortic valve", "Ebstein anomaly", "Mitral valve prolapse"]', 1, 'Up to 85% of patients with coarctation of the aorta also have a bicuspid aortic valve. (Blueprints)'),
    (v_topic_id, '200: A neonate with critical Coarctation of the Aorta presents with sudden shock and severe acidosis on day 3 of life. What is the immediate life-saving intervention?', '["Intravenous Indomethacin", "Immediate heart transplant", "Intravenous Prostaglandin E1", "Intravenous fluid bolus alone"]', 2, 'In critical coarctation, lower body perfusion is ductal-dependent. Closure of the PDA leads to shock. PGE1 reopens the ductus. (Nelson Essentials)'),
    (v_topic_id, '201: A 2-month-old female toddler presents with cyanosis during episodes of crying or feeding. The cyanosis improves when the child is placed in a knee-chest position. What is the most likely diagnosis?', '["Tricuspid Atresia", "Tetralogy of Fallot", "Truncus Arteriosus", "Transposition of the Great Arteries"]', 1, 'These ''tet spells'' are characteristic of Tetralogy of Fallot. The knee-chest position increases systemic vascular resistance, decreasing the right-to-left shunt and improving pulmonary blood flow. (Nelson Essentials)'),
    (v_topic_id, '202: Which of the following is NOT one of the four classic components of Tetralogy of Fallot?', '["Ventricular Septal Defect", "Right Ventricular Hypertrophy", "Atrial Septal Defect", "Pulmonary Stenosis"]', 2, 'The components (PROVe) are Pulmonary stenosis (RV outflow tract obstruction), Right ventricular hypertrophy, Overriding aorta, and VSD. (BRS Pediatrics)'),
    (v_topic_id, '203: What is the classic chest X-ray finding in a patient with Tetralogy of Fallot?', '["Egg on a string", "Figure 3 sign", "Boot-shaped heart (Coeur en sabot)", "Snowman sign"]', 2, 'The boot-shaped heart is due to right ventricular hypertrophy (upturned apex) and a concave main pulmonary artery segment. (Case Files Pediatrics)'),
    (v_topic_id, '204: In Tetralogy of Fallot, the degree of cyanosis and clinical severity is most primarily determined by the severity of:', '["Right ventricular outflow tract obstruction (Pulmonary stenosis)", "The amount of right ventricular hypertrophy", "The degree of aortic override", "The size of the VSD"]', 0, 'The severity of pulmonary stenosis dictates the amount of right-to-left shunting across the VSD, which determines the degree of cyanosis. (Blueprints)'),
    (v_topic_id, '205: A 1-year-old with Tetralogy of Fallot presents with an acute hypercyanotic spell (Tet spell). After placing the child in a knee-chest position, which medication is most appropriate to administer?', '["Epinephrine", "Diuretics", "Digoxin", "Morphine and Oxygen"]', 3, 'Management of a Tet spell includes knee-chest position, oxygen, morphine (decreases sympathetic drive and infundibular spasm), and IV fluids. Beta-blockers or phenylephrine can also be used. (Nelson Essentials)'),
    (v_topic_id, '206: A neonate presents with profound cyanosis immediately after birth. Echocardiogram reveals that the aorta arises from the right ventricle and the pulmonary artery from the left ventricle. What is the diagnosis?', '["Total Anomalous Pulmonary Venous Return", "Tetralogy of Fallot", "Transposition of the Great Arteries (TGA)", "Truncus Arteriosus"]', 2, 'TGA is the most common cyanotic heart defect presenting in the immediate newborn period. It creates two parallel circulatory systems. (Nelson Essentials)'),
    (v_topic_id, '207: In a newborn with Transposition of the Great Arteries, survival before surgical repair depends entirely on:', '["Administering Indomethacin", "Administration of 100% oxygen", "Mixing of blood via a PDA, ASD, or VSD", "Keeping the infant in a knee-chest position"]', 2, 'Because the pulmonary and systemic circulations are in parallel, life is impossible without mixing of oxygenated and deoxygenated blood through a shunt (PDA, PFO/ASD, or VSD). (Blueprints)'),
    (v_topic_id, '208: What is the classic chest X-ray appearance in a neonate with Transposition of the Great Arteries?', '["Boot-shaped heart", "''Egg on a string'' with a narrow mediastinum", "Wall-to-wall heart", "Snowman sign"]', 1, 'The ''egg on a string'' appearance is due to the anteroposterior relationship of the great vessels (causing a narrow superior mediastinum) and a globular heart. (BRS Pediatrics)'),
    (v_topic_id, '209: If Prostaglandin E1 fails to improve oxygenation in a severely cyanotic neonate with Transposition of the Great Arteries, what is the next best step?', '["Immediate open-heart surgery", "High-frequency oscillatory ventilation", "Balloon atrial septostomy (Rashkind procedure)", "Administration of Indomethacin"]', 2, 'If the PFO is restrictive and PGE1 isn''t enough, a balloon atrial septostomy is performed via catheterization to tear the atrial septum and improve mixing. (Case Files Pediatrics)'),
    (v_topic_id, '210: Transposition of the Great Arteries is strongly associated with which maternal condition?', '["Maternal rubella infection", "Maternal lupus", "Maternal diabetes mellitus", "Maternal lithium use"]', 2, 'Infants of diabetic mothers have a significantly increased risk of congenital heart defects, including TGA, VSD, and hypertrophic cardiomyopathy. (Nelson Essentials)'),
    (v_topic_id, '211: A neonate is found to have a single large vessel arising from the base of the heart that gives rise to the coronary, pulmonary, and systemic arteries. A VSD is also present. Diagnosis?', '["Truncus Arteriosus", "Tricuspid Atresia", "Transposition of the Great Arteries", "Tetralogy of Fallot"]', 0, 'Truncus arteriosus involves failure of the conotruncal septum to form, resulting in a single great vessel and a mandatory VSD. (Blueprints)'),
    (v_topic_id, '212: Truncus Arteriosus and Tetralogy of Fallot are frequently associated with microdeletion of chromosome 22q11. What syndrome is this?', '["Williams syndrome", "Turner syndrome", "Down syndrome", "DiGeorge syndrome"]', 3, 'DiGeorge syndrome (22q11.2 deletion) is associated with conotruncal cardiac defects (Truncus, ToF), abnormal facies, thymic hypoplasia, cleft palate, and hypocalcemia. (Nelson Essentials)'),
    (v_topic_id, '213: A cyanotic newborn has an ECG showing Left Axis Deviation and Left Ventricular Hypertrophy (LVH). Right ventricular forces are completely absent. What is the most likely diagnosis?', '["Transposition of the Great Arteries", "Tetralogy of Fallot", "Pulmonary Stenosis", "Tricuspid Atresia"]', 3, 'Most cyanotic congenital heart defects present with Right Axis Deviation and RVH. Tricuspid Atresia is unique as it causes hypoplasia of the RV, leading to LAD and LVH. (Case Files Pediatrics)'),
    (v_topic_id, '214: For an infant with Tricuspid Atresia to survive, blood must bypass the right atrium. What obligatory defect must be present?', '["Pulmonary Atresia", "Coarctation of the Aorta", "Aortic Stenosis", "Atrial Septal Defect (ASD) or Patent Foramen Ovale (PFO)"]', 3, 'Since the tricuspid valve is absent, all systemic venous blood must cross the atrial septum (via ASD/PFO) to the left atrium to reach the left ventricle. (Blueprints)'),
    (v_topic_id, '215: A neonate with cyanosis has a chest X-ray demonstrating a ''snowman'' (or figure-8) appearance of the cardiac silhouette. What is the diagnosis?', '["Coarctation of the Aorta", "Tetralogy of Fallot", "Total Anomalous Pulmonary Venous Return (TAPVR)", "Transposition of the Great Arteries"]', 2, 'In TAPVR, all pulmonary veins drain into the systemic venous circulation (e.g., SVC). The dilated vertical vein and SVC above the heart create the ''head'' of the snowman. (Nelson Essentials)'),
    (v_topic_id, '216: A neonate presents with cyanosis. Echocardiogram shows downward displacement of the tricuspid valve leaflets into the right ventricle, causing ''atrialization'' of the right ventricle. Diagnosis?', '["Ebstein Anomaly", "Tetralogy of Fallot", "Tricuspid Atresia", "Truncus Arteriosus"]', 0, 'Ebstein anomaly is characterized by apical displacement of the tricuspid valve, leading to a small functional RV and severe tricuspid regurgitation. (Blueprints)'),
    (v_topic_id, '217: Maternal use of which psychiatric medication during pregnancy is classically associated with Ebstein Anomaly?', '["Valproic acid", "Carbamazepine", "Lithium", "SSRI (e.g., Fluoxetine)"]', 2, 'Lithium exposure in the first trimester is classically linked to a higher risk of Ebstein anomaly. (BRS Pediatrics)'),
    (v_topic_id, '218: Patients with Ebstein Anomaly have a high incidence of which cardiac arrhythmia?', '["Ventricular Fibrillation", "Wolff-Parkinson-White (WPW) syndrome", "First-degree AV block", "Torsades de pointes"]', 1, 'Ebstein anomaly is strongly associated with accessory conduction pathways, leading to WPW syndrome and supraventricular tachycardias. (Nelson Essentials)'),
    (v_topic_id, '219: A 4-year-old newborn presents with shock, weak pulses, and gray cyanosis shortly after the ductus arteriosus begins to close. Echocardiogram shows a severely underdeveloped left ventricle. Diagnosis?', '["Ebstein Anomaly", "Tetralogy of Fallot", "Hypoplastic Left Heart Syndrome (HLHS)", "Tricuspid Atresia"]', 2, 'HLHS involves hypoplasia of the left ventricle, mitral valve, and aorta. Systemic blood flow is entirely dependent on a Patent Ductus Arteriosus (PDA). (Case Files Pediatrics)'),
    (v_topic_id, '220: What is the primary staged surgical palliation pathway for Hypoplastic Left Heart Syndrome (HLHS)?', '["Ross procedure", "Norwood procedure, followed by Glenn, then Fontan", "Blalock-Taussig shunt alone", "Arterial switch operation"]', 1, 'The Norwood procedure (stage 1) constructs a new aorta, followed by the bidirectional Glenn (stage 2), and the Fontan completion (stage 3) to route venous return directly to the lungs. (Nelson Essentials)'),
    (v_topic_id, '221: Which of the following is an acyanotic congenital heart defect?', '["Transposition of the Great Arteries", "Truncus Arteriosus", "Tetralogy of Fallot", "Ventricular Septal Defect"]', 3, 'VSD, ASD, and PDA are left-to-right shunts, which are acyanotic. The ''5 Ts'' (ToF, TGA, Truncus, Tricuspid Atresia, TAPVR) are right-to-left shunts and are cyanotic. (Blueprints)'),
    (v_topic_id, '222: The ''5 Ts'' of cyanotic congenital heart disease include all EXCEPT:', '["Tachycardia induced cardiomyopathy", "Truncus Arteriosus", "Tetralogy of Fallot", "Transposition of the Great Arteries"]', 0, 'The 5 Ts are Tetralogy, Transposition, Truncus, Tricuspid Atresia, and TAPVR. (BRS Pediatrics)'),
    (v_topic_id, '223: Which of the following patients requires antibiotic prophylaxis prior to a dental procedure?', '["A child with a physiologic flow murmur", "A child with an unrepaired cyanotic congenital heart defect", "A child with a history of Kawasaki disease without aneurysms", "A child with an isolated, repaired ASD (surgery 2 years ago)"]', 1, 'Endocarditis prophylaxis is recommended for unrepaired cyanotic CHD, completely repaired CHD within the first 6 months, repaired CHD with residual defects, or prior history of endocarditis. (AHA Guidelines/Nelson)'),
    (v_topic_id, '224: A 2-month-old presents with 5 days of fever, bilateral non-exudative conjunctivitis, strawberry tongue, cervical lymphadenopathy, and a polymorphous rash. What is the most critical cardiac complication to prevent?', '["Aortic dissection", "Rheumatic mitral stenosis", "Ventricular septal rupture", "Coronary artery aneurysms"]', 3, 'This is classic Kawasaki disease. The primary goal of treatment with IVIG and aspirin is to prevent the development of coronary artery aneurysms. (Nelson Essentials)'),
    (v_topic_id, '225: A 1-day-old immigrant presents with a history of recurrent sore throats and now has a new, rumbling diastolic murmur at the apex with an opening snap. What is the most likely diagnosis?', '["Congenital aortic stenosis", "Rheumatic mitral stenosis", "Ventricular Septal Defect", "Infective endocarditis"]', 1, 'A rumbling diastolic murmur with an opening snap is classic for mitral stenosis, which is almost always a late consequence of Rheumatic Heart Disease following Group A Strep pharyngitis. (Blueprints)'),
    (v_topic_id, '226: A 2-month-old male toddler is evaluated for a murmur. A harsh, holosystolic murmur is heard best at the parasternal border. The child is asymptomatic and growing well. What is the most likely diagnosis?', '["Coarctation of the Aorta", "Atrial Septal Defect (ASD)", "Ventricular Septal Defect (VSD)", "Patent Ductus Arteriosus (PDA)"]', 2, 'VSD is the most common congenital heart defect, presenting with a harsh, holosystolic murmur at the left lower sternal border. Small VSDs are asymptomatic. (Nelson Essentials)'),
    (v_topic_id, '227: A 3-month-old girl with a known large VSD presents with tachypnea, diaphoresis during feeds, and poor weight gain. What is the most appropriate initial medical therapy?', '["Immediate surgical closure", "Indomethacin", "Diuretics (e.g., Furosemide) and high-calorie formula", "Prostaglandin E1"]', 2, 'Infants with large VSDs and heart failure are initially managed medically with diuretics and nutritional support to allow for growth before surgical repair. (Nelson Essentials)'),
    (v_topic_id, '228: In a patient with a Ventricular Septal Defect, the development of pulmonary hypertension and reversal of the shunt (right-to-left) leading to cyanosis is known as:', '["Eisenmenger syndrome", "Cor pulmonale", "Tetralogy of Fallot", "Ebstein anomaly"]', 0, 'Eisenmenger syndrome occurs when chronic left-to-right shunting causes pulmonary vascular disease, eventually reversing the shunt and causing cyanosis. (Blueprints)'),
    (v_topic_id, '229: Which of the following describes the typical natural history of a small, restrictive Ventricular Septal Defect?', '["High risk of sudden cardiac death", "Spontaneous closure in childhood", "Progression to heart failure", "Development of Eisenmenger syndrome"]', 1, 'The majority of small, muscular VSDs close spontaneously during childhood and do not require surgical intervention. (BRS Pediatrics)'),
    (v_topic_id, '230: A 1-day-old female infant has a holosystolic murmur at the left lower sternal border. An echocardiogram shows a large VSD. Which of the following chamber enlargements is most likely?', '["Left atrium only", "Right atrium and Right ventricle", "Left atrium and Left ventricle", "Right ventricle only"]', 2, 'A large VSD causes a left-to-right shunt. The extra blood goes to the lungs and returns to the left heart, causing LA and LV volume overload and dilation. (Nelson Essentials)'),
    (v_topic_id, '231: A 6-month-old male toddler is found to have a widely split and fixed S2 on routine examination. There is also a soft systolic ejection murmur at the left upper sternal border. What is the most likely diagnosis?', '["Atrial Septal Defect (ASD)", "Tetralogy of Fallot", "Pulmonary Stenosis", "Ventricular Septal Defect (VSD)"]', 0, 'A widely split and fixed S2 is the hallmark of an ASD. The systolic murmur is due to increased flow across the pulmonary valve. (Case Files Pediatrics)'),
    (v_topic_id, '232: An ostium primum Atrial Septal Defect is most commonly associated with which genetic syndrome?', '["Marfan syndrome", "Turner syndrome", "Down syndrome (Trisomy 21)", "DiGeorge syndrome"]', 2, 'Ostium primum ASDs and Atrioventricular Septal Defects (AVSDs) are highly associated with Down syndrome. (Blueprints)'),
    (v_topic_id, '233: What is the primary hemodynamic consequence of an unrepaired moderate-to-large Atrial Septal Defect over decades?', '["Right-sided heart volume overload and failure", "Premature coronary artery disease", "Left ventricular hypertrophy", "Aortic root dilation"]', 0, 'Chronic left-to-right shunting through an ASD leads to right atrial and right ventricular volume overload, eventually causing right heart failure or arrhythmias in adulthood. (BRS Pediatrics)'),
    (v_topic_id, '234: A 2-year-old male toddler with an unrepaired ASD presents with a sudden onset stroke. What is the most likely mechanism?', '["Infective endocarditis", "Atherosclerotic plaque rupture", "Hemorrhage from a berry aneurysm", "Paradoxical embolus"]', 3, 'A venous thrombus can cross through the ASD (right-to-left shunting during transient pressure changes) into the systemic circulation, causing a paradoxical embolus and stroke. (Nelson Essentials)'),
    (v_topic_id, '235: Which type of Atrial Septal Defect is the most common?', '["Sinus venosus", "Coronary sinus", "Ostium primum", "Ostium secundum"]', 3, 'The ostium secundum defect, located in the central portion of the atrial septum, is the most common type of ASD. (Blueprints)'),
    (v_topic_id, '236: A 1-week-old premature infant has a continuous, machine-like murmur heard best at the left infraclavicular area. Bounding peripheral pulses are noted. What is the most likely diagnosis?', '["Patent Ductus Arteriosus (PDA)", "Aortic Regurgitation", "Coarctation of the Aorta", "Truncus Arteriosus"]', 0, 'A continuous machine-like murmur and bounding pulses (due to widened pulse pressure) are classic findings of a Patent Ductus Arteriosus. (Nelson Essentials)'),
    (v_topic_id, '237: What medication is used to induce closure of a Patent Ductus Arteriosus in a premature infant?', '["Indomethacin (or Ibuprofen)", "Spironolactone", "Prostaglandin E1", "Acetaminophen"]', 0, 'NSAIDs like indomethacin or ibuprofen inhibit prostaglandin synthesis, which promotes the closure of the ductus arteriosus. (BRS Pediatrics)'),
    (v_topic_id, '238: In which of the following congenital heart defects is a Patent Ductus Arteriosus essential for survival (ductal-dependent)?', '["Atrial Septal Defect", "Transposition of the Great Arteries", "Mild Pulmonary Stenosis", "Small Ventricular Septal Defect"]', 1, 'In Transposition of the Great Arteries, mixing of oxygenated and deoxygenated blood is required for survival, making it a ductal-dependent lesion. (Case Files Pediatrics)'),
    (v_topic_id, '239: Maternal infection with which organism during the first trimester is classically associated with Patent Ductus Arteriosus?', '["Rubella", "Cytomegalovirus", "Toxoplasma gondii", "Herpes Simplex Virus"]', 0, 'Congenital rubella syndrome is classically associated with cataracts, sensorineural hearing loss, and congenital heart defects, most notably PDA and pulmonary artery stenosis. (Nelson Essentials)'),
    (v_topic_id, '240: Which medication is administered to maintain the patency of the ductus arteriosus in a newborn with ductal-dependent congenital heart disease?', '["Prostaglandin E1 (Alprostadil)", "Milrinone", "Epinephrine", "Indomethacin"]', 0, 'Prostaglandin E1 is used to keep the ductus arteriosus open until surgical intervention can be performed in ductal-dependent lesions. (Blueprints)'),
    (v_topic_id, '241: A 1-month-old female infant is found to have hypertension in the upper extremities and diminished, delayed femoral pulses. What is the most likely diagnosis?', '["Aortic Stenosis", "Renal Artery Stenosis", "Coarctation of the Aorta", "Patent Ductus Arteriosus"]', 2, 'Coarctation of the aorta presents with a blood pressure discrepancy between the upper and lower extremities and decreased or delayed femoral pulses. (Nelson Essentials)'),
    (v_topic_id, '242: Which genetic syndrome has a high association with Coarctation of the Aorta?', '["Marfan syndrome", "Down syndrome", "Turner syndrome", "DiGeorge syndrome"]', 2, 'Turner syndrome (45,X) is strongly associated with left-sided heart lesions, particularly coarctation of the aorta and bicuspid aortic valve. (BRS Pediatrics)'),
    (v_topic_id, '243: A chest X-ray of an older child with undiagnosed Coarctation of the Aorta is most likely to show:', '["Boot-shaped heart", "Snowman sign", "Rib notching and a ''''figure 3'''' sign", "Egg on a string appearance"]', 2, 'Rib notching is caused by enlarged collateral intercostal arteries. The ''figure 3'' sign is formed by the pre-stenotic dilation, the coarctation itself, and the post-stenotic dilation. (Case Files Pediatrics)'),
    (v_topic_id, '244: Coarctation of the Aorta is most commonly associated with which other congenital cardiac anomaly?', '["Pulmonary atresia", "Ebstein anomaly", "Bicuspid aortic valve", "Mitral valve prolapse"]', 2, 'Up to 85% of patients with coarctation of the aorta also have a bicuspid aortic valve. (Blueprints)'),
    (v_topic_id, '245: A neonate with critical Coarctation of the Aorta presents with sudden shock and severe acidosis on day 3 of life. What is the immediate life-saving intervention?', '["Intravenous fluid bolus alone", "Intravenous Indomethacin", "Intravenous Prostaglandin E1", "Immediate heart transplant"]', 2, 'In critical coarctation, lower body perfusion is ductal-dependent. Closure of the PDA leads to shock. PGE1 reopens the ductus. (Nelson Essentials)'),
    (v_topic_id, '246: A 2-month-old female toddler presents with cyanosis during episodes of crying or feeding. The cyanosis improves when the child is placed in a knee-chest position. What is the most likely diagnosis?', '["Tetralogy of Fallot", "Transposition of the Great Arteries", "Truncus Arteriosus", "Tricuspid Atresia"]', 0, 'These ''tet spells'' are characteristic of Tetralogy of Fallot. The knee-chest position increases systemic vascular resistance, decreasing the right-to-left shunt and improving pulmonary blood flow. (Nelson Essentials)'),
